insert into ponew values
(1, 1, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Gastric residual volumes in an enterally fed ICU patient are:', '["Never checked in any enterally fed ICU patient", "Only one sign of tolerance, alongside abdominal examination", "The only reliable measure of feed tolerance in ICU", "Used to calculate the patient''s daily calorie needs"]'::jsonb, 1, 'Feeds are not stopped for moderate residuals without other signs.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 2, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Musculoskeletal injuries in nurses are most often caused by:', '["Writing notes", "Talking to patients", "Lifting and moving patients", "Hand washing"]'::jsonb, 2, 'Use hoists, slide sheets and enough staff.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 3, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Personal protective equipment is considered:', '["The first and only control needed", "A substitute for safe systems", "Unnecessary in theatre", "The last line of defence against hazards"]'::jsonb, 3, 'Other controls should be used first.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 4, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Chest physiotherapy with percussion is contraindicated in:', '["Unstable rib fractures and active bleeding", "Cystic fibrosis with thick sputum", "Lobar atelectasis on the chest X-ray", "Retained secretions in the lower lobes"]'::jsonb, 0, 'It may worsen injury or bleeding.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 5, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Mendelson''s syndrome is:', '["A type of spinal headache", "Chemical pneumonitis from aspiration of acidic gastric contents", "Allergy to latex gloves", "A heart rhythm problem caused by volatile anaesthetic agents"]'::jsonb, 1, 'Risk is higher in pregnancy, obesity and full stomach.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 6, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A nurse with an open cut on the hand should, before scrubbing:', '["Use alcohol on the cut and continue", "Report it and cover it with a waterproof dressing, or not scrub", "Scrub as usual without a cover", "Hide it from the team"]'::jsonb, 1, 'Broken skin increases the risk of bloodborne virus exposure.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 7, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The best teaching method for ICU nurses learning ventilator setup is:', '["Watching through the window from outside the room", "A lecture in a classroom with no practical session", "Demonstration with supervised practice and return demonstration", "Reading the ventilator manual alone at home"]'::jsonb, 2, 'Psychomotor skills need practice.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 8, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A nurse is caring for a patient who is sedated. The nurse should ensure that the patient''s dignity is maintained by:', '["Only providing care when the patient''s family is present", "Leaving the patient''s door open", "Talking about the patient''s condition with other staff members in front of them", "Providing privacy and explaining all care procedures to the patient, even if they are unresponsive"]'::jsonb, 3, 'Even if a patient is unresponsive, they may still be able to hear. The nurse should provide privacy, explain all care procedures in a respectful manner, and treat the patient as if they are conscious to maintain their dignity.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 9, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Early defibrillation in a shockable cardiac arrest rhythm is important because:', '["It should always be delayed until advanced life support arrives", "It has no effect on survival", "It is only effective after 30 minutes of CPR", "Survival chances decrease significantly with every minute of delay"]'::jsonb, 3, 'For shockable rhythms, survival probability drops substantially with each minute defibrillation is delayed, making early defibrillation a survival priority.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 10, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A safety data sheet (SDS) for a chemical gives information on:', '["The supplier''s staff names", "Hazards, safe handling, first aid and disposal", "The chemical''s price", "Theatre schedules"]'::jsonb, 1, 'It must be available for every hazardous substance.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 11, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A ''high'' or total spinal block presents with:', '["Hypertension and tachycardia, with normal arm power", "Leg pain and tingling only, settling within one hour", "Hypotension, bradycardia, arm weakness, breathing difficulty", "Increased urine output with flushing and a mild headache"]'::jsonb, 2, 'Excessive cephalad spread blocks the cardiac accelerators and phrenic nerves. Management is airway support, ventilation, fluids, vasopressors and atropine.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 12, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Nutritional deficiencies can occur postoperatively in the ICU. Which vitamin deficiency is commonly seen in surgical patients?', '["Vitamin C", "Vitamin D", "Vitamin A", "Vitamin B12"]'::jsonb, 3, 'Vitamin B12 and other nutrient deficiencies are recognised risks after major surgery, particularly with reduced intake or malabsorption.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 13, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The motor contraction called fasciculation is seen after the use of one of the following', '["Pavlun", "Marcaine", "Suxamethonium", "Pethadine"]'::jsonb, 2, 'Fasciculations (visible muscle twitching) are a characteristic effect of succinylcholine (suxamethonium) after administration.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 14, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Exposure to anaesthetic gases is reduced by:', '["Scavenging and good theatre ventilation", "Using open face masks without seals", "Avoiding maintenance of the machines", "Closing all theatre ventilation systems"]'::jsonb, 0, 'Chronic exposure may cause headaches and reproductive risks.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 15, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'After renal transplant, a sudden fall in urine output with graft tenderness and fever suggests:', '["Over-hydration from excess IV fluids", "A normal post-operative recovery pattern", "Acute rejection or graft vessel thrombosis", "Hypoglycaemia caused by the steroids"]'::jsonb, 2, 'Urgent ultrasound, Doppler and biopsy may be needed.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 16, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A nurse is administering a sedative to a patient for a procedure. The nurse knows that the most common class of sedatives used for procedural sedation is:', '["Beta-blockers", "Benzodiazepines", "Opioids", "Antibiotics"]'::jsonb, 1, 'Benzodiazepines, such as Midazolam, are the most common class of sedatives used for procedural sedation. They provide anxiolysis (anxiety reduction) and amnesia, which helps to make the patient more comfortable during the procedure.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 17, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A key principle of adult learning (andragogy) when teaching ICU staff is that adults:', '["Learn best by memorising facts without any context", "Prefer lectures with no participation or discussion", "Do not need any feedback on their performance", "Learn best when content is relevant and builds on experience"]'::jsonb, 3, 'Knowles described self-direction, experience and problem-centred learning.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 18, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A patient is at risk for developing post-operative fluid and electrolyte imbalances. What nursing interventions can help prevent or manage fluid and electrolyte imbalances in the post- operative period?', '["Encourage the patient to limit fluid intake", "Administer IV fluids as prescribed", "Monitor the patient''s intake and output closely", "Restrict the patient''s sodium intake"]'::jsonb, 2, 'Close monitoring of fluid intake and output helps detect and guide correction of postoperative fluid and electrolyte imbalances.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 19, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Occupational health records of staff should be:', '["Given to patients", "Posted on the notice board", "Kept confidential", "Shared with all colleagues"]'::jsonb, 2, 'Only shared with consent or legal need.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 20, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Hepatitis B vaccination for theatre staff is followed by:', '["A blood test to check antibody response", "A hearing test", "No follow-up ever", "A chest X-ray"]'::jsonb, 0, 'Non-responders need further assessment.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 21, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Formaldehyde used for specimens is hazardous because it is:', '["A vitamin", "Safe to breathe", "Irritant and a possible carcinogen", "Harmless to skin"]'::jsonb, 2, 'Use pre-filled containers and good ventilation.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 22, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The RACE fire acronym stands for:', '["Respond, Act, Clean, Evaluate", "Remove, Ask, Call, Escape", "Run, Alert, Close, Exit", "Rescue, Alarm, Contain, Extinguish/Evacuate"]'::jsonb, 3, 'Remove people from danger first.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 23, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Before moving a heavy load, the nurse should first:', '["Assess the task, the load, the environment and individual ability", "Lift alone without help", "Lift quickly to get it over with", "Twist the back while lifting"]'::jsonb, 0, 'This is a manual handling risk assessment (TILE).', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 24, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Which of the following is an example of an anthropometric measurement used in nutritional assessment?', '["White blood cell count", "C-reactive protein level", "Mid-upper arm circumference", "Serum albumin level"]'::jsonb, 2, 'Anthropometric measurements assess body size and composition and include height, weight, BMI, mid-upper arm circumference, and triceps skinfold thickness.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 25, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'An ICU patient is at risk for developing complications related to immobility. What nursing interventions can help prevent complications of immobility?', '["Restraining the patient to prevent falls", "Encouraging regular range of motion exercises", "Keeping the patient in bed at all times", "Limiting bathroom privileges"]'::jsonb, 1, 'Regular range-of-motion exercises help prevent the deconditioning, contractures, and thromboembolic risks associated with immobility.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 26, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A post-operative patient is at risk for developing adhesion formation. What nursing interventions can help prevent or minimize adhesion formation?', '["Administer antibiotics prophylactically", "Encourage deep breathing exercises", "Prevent unnecessary manipulation of the surgical site", "Apply warm compresses to the surgical site"]'::jsonb, 2, 'Minimising unnecessary handling/manipulation of the surgical site reduces additional tissue trauma that contributes to adhesion formation.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 27, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'In postoperative care, what is a common complication associated with inadequate pain management?', '["Urinary retention", "Respiratory depression", "Increased appetite", "Hypotension"]'::jsonb, 1, 'Under-treated pain can suppress respiratory effort indirectly through splinting/shallow breathing, but more directly, opioid analgesics used to treat pain carry a dose-dependent risk of respiratory depression.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 28, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'What is a common sign of infection in a postoperative patient?', '["Decreased pain at the incision site", "Redness and warmth at the surgical site", "Decreased white blood cell count", "Increased appetite"]'::jsonb, 1, 'Redness and warmth at the surgical site are classic local signs of wound infection.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 29, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A nurse is administering Ketamine to a patient for a procedural sedation. The nurse should be aware of which of the following side effects?', '["Respiratory depression and hypothermia", "Bradycardia and hypotension", "Hallucinations and increased salivation", "Hypoglycemia"]'::jsonb, 2, 'Ketamine is a dissociative anesthetic that can cause hallucinations and vivid dreams as the patient emerges from the sedation. It can also cause an increase in salivation, which requires the nurse to monitor for and manage secretions to prevent aspiration.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 30, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A slippery theatre floor after a spillage should be:', '["Left to dry by itself", "Ignored if the case is busy", "Covered with paper towels only", "Cleaned immediately and marked with a warning sign"]'::jsonb, 3, 'Slips and falls are common injuries.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 31, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'A contraindication to neuraxial (spinal/epidural) anaesthesia is:', '["Coagulopathy or infection at the injection site", "Patient preference for regional technique", "Stable vital signs", "Mild anxiety"]'::jsonb, 0, 'Coagulopathy risks epidural/spinal haematoma, and local infection risks introducing pathogens into the CSF or epidural space — both are recognised contraindications.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 32, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'Incentive spirometry after thoracic or abdominal surgery mainly prevents:', '["Atelectasis and pneumonia", "Deep vein thrombosis", "Urinary retention", "Pressure ulcers"]'::jsonb, 0, 'Slow, deep, sustained inspiration re-expands alveoli.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 33, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'To reduce post dural puncture head ache with spinal we use', '["Wide bore spinal needle", "Small fine spinal needle", "Tohy needle", "Syringe"]'::jsonb, 1, 'Using a smaller-gauge (fine) spinal needle reduces the size of the dural puncture and lowers the risk of post-dural puncture headache.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 34, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'An ICU patient has a central venous catheter in place. What nursing interventions are essential to prevent complications associated with central lines?', '["Keeping the catheter site dry and exposed to air", "Allowing family members to touch the catheter site", "Maintaining a sterile technique during catheter care and dressing changes", "Removing the catheter as soon as possible to prevent infection"]'::jsonb, 2, 'Strict sterile technique during central line care and dressing changes reduces the risk of catheter-related bloodstream infection.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 35, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 411 · Fundamentals of Nursing Anaesthesia', 'The purpose of pre-oxygenation before induction is to:', '["Increase blood pressure before the induction agent is given", "Reduce gastric acid volume and so the risk of aspiration", "Replace lung nitrogen with oxygen, extending safe apnoea time", "Sedate the patient so the induction dose can be reduced"]'::jsonb, 2, 'Breathing 100% oxygen through a tight mask for about 3 minutes (end-tidal O2 above 80-90%) gives the anaesthetist more time before desaturation during intubation.', 'NAP 411 · Fundamentals of Nursing Anaesthesia'),
(1, 36, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The openings located on either side of the vaginal orifice are the:', '["Urethral meatus", "Bartholin''s ducts", "Skene''s ducts", "Hymenal ducts"]'::jsonb, 1, 'Bartholin''s (greater vestibular) gland ducts open on either side of the vaginal orifice. Skene''s ducts open beside the urethra.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 37, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Which spinal nerves give rise to the cervical plexus?', '["T1–T12", "C3–T3", "C1–C4", "C5–T1"]'::jsonb, 2, 'The cervical plexus is formed by the anterior rami of C1–C4. C5–T1 form the brachial plexus.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 38, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The approximate daily volume of glomerular filtrate in an adult is:', '["180 L in males and about 150 L in females", "300 L in both sexes", "50 L in males and 90 L in females", "120 L in males and 130 L in females"]'::jsonb, 0, 'The kidneys filter about 180 L of plasma a day (GFR about 125 mL/min) in adult men, slightly less in women.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 39, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The normal arterial blood pH range is:', '["6.80–7.00", "7.00–7.20", "7.35–7.45", "7.50–7.65"]'::jsonb, 2, 'Below 7.35 is acidaemia, above 7.45 is alkalaemia. Normal PaCO₂ is 35–45 mmHg and bicarbonate 22–26 mmol/L.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 40, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The 6th cranial nerve is the:', '["Oculomotor nerve", "Facial nerve", "Trigeminal nerve", "Abducent nerve"]'::jsonb, 3, 'Cranial nerve VI, the abducent (abducens) nerve, supplies the lateral rectus, which abducts the eye.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 41, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The metabolic stress response to major surgery typically causes:', '["Lowered cortisol and catecholamines, with increased urine output and diuresis", "Reduced ADH and aldosterone, with dilute polyuria and sodium loss in the urine", "Raised cortisol, catecholamines and ADH, with fluid retention and hyperglycaemia", "Hypoglycaemia, with decreased protein breakdown and positive nitrogen balance"]'::jsonb, 2, 'Surgery activates the hypothalamic–pituitary–adrenal axis and sympathetic system: cortisol, glucagon, catecholamines, ADH and aldosterone rise, causing catabolism, hyperglycaemia and fluid retention with low urine output in the first 24–48 h.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 42, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Antidiuretic hormone (ADH) increases water reabsorption mainly in the:', '["Ascending limb of the loop of Henle", "Glomerulus", "Collecting ducts of the nephron", "Proximal convoluted tubule"]'::jsonb, 2, 'ADH (from the posterior pituitary) inserts aquaporin channels into collecting-duct cells. Surgery and pain increase ADH secretion, causing water retention after operations.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 43, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The short period that occurs during the transmission of impulses through the synapses is:', '["Synaptic delay", "Synaptic junction", "Synaptic cleft", "Synaptic simulation"]'::jsonb, 0, 'Synaptic delay (about 0.5 ms) is the time taken for neurotransmitter release, diffusion and receptor binding at a synapse.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 44, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'If stroke volume is 70 mL and heart rate is 75 beats/min, the cardiac output is:', '["5.25 L/min", "52.5 L/min", "0.525 L/min", "1.07 L/min"]'::jsonb, 0, 'Cardiac output = stroke volume × heart rate = 70 mL × 75 = 5,250 mL/min = 5.25 L/min (normal 4–8 L/min).', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 45, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Which meningeal layer lies closest to the brain surface?', '["Dura mater", "Periosteum", "Pia mater", "Arachnoid mater"]'::jsonb, 2, 'The pia mater is the innermost, delicate meningeal layer that closely adheres to the surface of the brain and spinal cord.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 46, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The right lung consists of which lobes?', '["Upper and lower lobes", "Lower lobe and lingula", "Only a posterior lobe", "Upper, middle and lower lobes"]'::jsonb, 3, 'The right lung has three lobes (upper, middle, lower). The left has two (upper with lingula, and lower).', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 47, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The normal adult serum potassium range is:', '["135–145 mmol/L", "1.5–2.5 mmol/L", "5.5–7.0 mmol/L", "3.5–5.0 mmol/L"]'::jsonb, 3, 'Potassium is mostly intracellular. Both hypokalaemia and hyperkalaemia cause arrhythmias, and anaesthesia (e.g. suxamethonium) and tissue damage can raise potassium. 135–145 mmol/L is the sodium range.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 48, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Cerebrospinal fluid (CSF) is mainly produced by the:', '["Choroid plexus in the ventricles", "Dura mater", "Arachnoid granulations", "Pineal gland"]'::jsonb, 0, 'About 500 mL/day is produced; the total volume is about 150 mL. It is reabsorbed through arachnoid granulations into the venous sinuses. Obstruction of flow causes hydrocephalus.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 49, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Transitional epithelium of the urinary bladder is best described as:', '["Changing shape depending on bladder fullness", "Containing a special elastic substance", "Changing from cuboidal to columnar", "A single, non-stratified layer"]'::jsonb, 0, 'Transitional epithelium (urothelium) is stratified and changes shape, from dome-shaped to flattened, as the bladder fills and stretches.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 50, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'A glomerulus and glomerular capsule together make up one:', '["Nephron", "Kidney lobule", "Renal capsule", "Renal corpuscle"]'::jsonb, 3, 'The glomerulus and Bowman''s (glomerular) capsule together form the renal corpuscle.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 51, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The rhythm of breathing is set by neurons in the:', '["Hypothalamus", "Pons", "Midbrain", "Medulla oblongata"]'::jsonb, 3, 'The basic rhythm of breathing is generated by medullary neurons (pre-Bötzinger complex). The pons modifies it.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 52, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Clotting factors are primarily synthesised by the:', '["Pancreas", "Liver", "Spleen", "Kidneys"]'::jsonb, 1, 'Most clotting factors are synthesised in the liver, which is why liver disease can impair coagulation.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 53, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The main function of the medulla oblongata is:', '["Endocrine control", "Cardiorespiratory control", "Parasympathetic control", "Renal control"]'::jsonb, 1, 'The medulla holds the cardiac, vasomotor and respiratory centres.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 54, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'A patient with blood group O negative is often called the:', '["Universal recipient", "Rh-positive donor", "Least compatible donor", "Universal donor"]'::jsonb, 3, 'O negative red cells lack A, B, and Rh(D) antigens, making them compatible (in emergencies) with recipients of any ABO/Rh type — hence ''universal donor''.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 55, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The olfactory tract terminates in which area of the brain?', '["Olfactory cortex", "Olfactory bulb", "Cribriform plate", "Visual cortex"]'::jsonb, 0, 'The olfactory tract carries impulses from the olfactory bulb to the primary olfactory cortex in the temporal lobe.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 56, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Neurones are also known as:', '["Axons", "Glial cells", "Nerve cells", "Ganglia"]'::jsonb, 2, 'Neurones are nerve cells, the functional units of the nervous system.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 57, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The hepatic portal vein primarily carries blood from the:', '["Heart to the liver", "Liver to the systemic circulation only", "Kidneys to the liver", "Gastrointestinal tract and spleen to the liver"]'::jsonb, 3, 'The hepatic portal vein drains nutrient- and sometimes toxin-rich blood from the GI tract and spleen into the liver for processing before it enters systemic circulation.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 58, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'A patient came to the ER with Difficulty in breathing; He was intubated and placed on Mechanical ventilation. His ABGs report showed that his PCO2 is 55 mm Hg. To wash out CO2 which of the following parameter(s) should be adjusted:', '["Fio2 and R/R", "Vt and PEEP", "PEEP and FiO2", "Vt and R/R"]'::jsonb, 3, 'Washing out CO2 means increasing minute ventilation — adjusting tidal volume and respiratory rate.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 59, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Which muscle aids deep (forced) expiration?', '["External intercostals", "Sternocleidomastoid", "Scalenes", "Rectus abdominis"]'::jsonb, 3, 'Forced (deep) expiration uses the abdominal muscles, such as rectus abdominis, and the internal intercostals. Scalenes, SCM and external intercostals are inspiratory.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 60, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'What is the body''s first metabolic pathway for breaking down glucose to release energy?', '["Glycolysis", "Glucosides", "Glycogenolysis", "Glycosides"]'::jsonb, 0, 'Glycolysis, in the cytoplasm, is the first pathway of glucose breakdown, giving pyruvate and 2 ATP.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 61, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Vitamin K is needed by the liver to produce clotting factors:', '["I, V and VIII", "XI, XII and XIII", "III, IV and VI", "II, VII, IX and X"]'::jsonb, 3, 'Warfarin blocks vitamin K–dependent factors II, VII, IX and X (and proteins C and S). Obstructive jaundice reduces vitamin K absorption, so it is given before biliary surgery.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 62, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The gag reflex primarily depends on which cranial nerve(s)?', '["Cranial nerves IX and X", "Cranial nerve XII only", "Cranial nerves I and II", "Cranial nerve VII only"]'::jsonb, 0, 'The glossopharyngeal (IX) and vagus (X) nerves mediate the sensory and motor components of the gag reflex, relevant to airway protection assessment.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 63, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'A patient was rushed to the clinic department due to hyperventilation. Which nursing intervention is the most appropriate for the client who is subsequently developing respiratory alkalosis?', '["Encouraging slow, deep breaths.", "Preparing to administer sodium bicarbonate.", "Administering sodium chloride I.V.", "Administer low-flow oxygen therapy."]'::jsonb, 0, 'Slow, deep breathing helps a hyperventilating patient retain CO2 and correct respiratory alkalosis.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 64, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Pulmonary surfactant, which reduces alveolar surface tension, is produced by:', '["Type I pneumocytes lining the alveoli", "Type II pneumocytes (type II alveolar cells)", "Goblet cells of the bronchial mucosa", "Alveolar macrophages (dust cells)"]'::jsonb, 1, 'Type I cells form the thin gas-exchange surface; type II cells secrete surfactant and can regenerate type I cells. Surfactant deficiency causes respiratory distress syndrome in preterm babies.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 65, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'A deficiency of pulmonary surfactant is most likely to cause:', '["COPD", "Atelectasis", "Pneumothorax", "Chronic bronchitis"]'::jsonb, 1, 'Surfactant lowers alveolar surface tension. Without it, alveoli collapse (atelectasis), as in neonatal respiratory distress syndrome.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 66, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Residual volume is the amount of air:', '["Inhaled during a normal breath", "Inhaled during maximal inspiration beyond tidal volume", "Exhaled forcefully after normal expiration", "Remaining in the lungs after maximal expiration"]'::jsonb, 3, 'Residual volume is the air that remains in the lungs even after the most forceful expiration, preventing lung collapse.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 67, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The approximate total body water content of an adult woman is:', '["50%", "80%", "70%", "60%"]'::jsonb, 0, 'Total body water is about 60% of body weight in adult men and about 50–55% in women, who have more body fat.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 68, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The adrenal medulla mainly secretes:', '["Adrenaline (epinephrine) and noradrenaline", "Cortisol and other glucocorticoids", "Aldosterone and other mineralocorticoids", "Antidiuretic hormone and oxytocin"]'::jsonb, 0, 'The adrenal cortex produces cortisol (zona fasciculata), aldosterone (zona glomerulosa) and sex hormones. The medulla is part of the sympathetic system and releases catecholamines.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 69, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'Which gastrointestinal process refers to the physical and chemical breakdown of food into absorbable units?', '["Digestion", "Excretion", "Absorption", "Transportation"]'::jsonb, 0, 'Digestion is the breakdown of food (mechanically and chemically) into smaller, absorbable molecules.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 70, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 410 · Applied Anatomy & Physiology I', 'The correct order of the main stages of haemostasis is:', '["Vascular spasm, platelet plug, then coagulation", "Coagulation, then vascular spasm, then platelet plug", "Platelet plug, fibrinolysis, then vascular spasm", "Fibrinolysis, coagulation, then the platelet plug"]'::jsonb, 0, 'Injury causes immediate vasoconstriction, then platelets adhere and aggregate, then the clotting cascade forms fibrin to stabilise the plug. Fibrinolysis later dissolves the clot.', 'NAP 410 · Applied Anatomy & Physiology I'),
(1, 71, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Which contrast media type is preferred in high-risk patients such as those with renal failure, cardiac failure, or diabetes mellitus?', '["No contrast is ever needed in high-risk patients", "Non-ionic (Low Osmolar) contrast media", "Barium sulfate only", "Ionic (High Osmolar) contrast media"]'::jsonb, 1, 'Non-ionic/Low Osmolar Contrast Media (LOCM) cause fewer reactions and are preferred in high-risk groups including renal failure, cardiac failure, diabetes, sickle cell disease and the elderly.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 72, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'On a chest X-ray, correct endotracheal tube tip position is approximately:', '["At the level of the carina", "At the level of the vocal cords", "2–4cm above the carina", "In the right mainstem bronchus"]'::jsonb, 2, 'The ETT tip should sit roughly 2–4cm above the carina (around the T2–T4 vertebral level) to avoid mainstem intubation or accidental extubation with head movement.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 73, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Barium enema is a contrast study used to examine the:', '["Lungs", "Kidneys", "Stomach only", "Large bowel"]'::jsonb, 3, 'Bowel preparation is needed. Barium is avoided if perforation is suspected.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 74, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Before an X-ray in a woman of reproductive age, the nurse should:', '["Ignore pregnancy status", "Check pregnancy status", "Give a sedative", "Remove all clothing"]'::jsonb, 1, 'The ''28-day rule'' or pregnancy test protects a possible fetus from radiation.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 75, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A pleural effusion typically becomes visible on a standard chest X-ray only once fluid volume reaches approximately:', '["150–300ml", "2–3 litres", "5–10ml", "There is no minimum volume — any amount is visible"]'::jsonb, 0, 'A pleural effusion generally needs to reach roughly 150–300ml before it becomes detectable on a standard chest X-ray.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 76, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A widened mediastinum on chest X-ray after trauma raises suspicion for:', '["Simple pneumonia", "Peptic ulcer perforation", "Normal anatomical variant in all patients", "Traumatic aortic injury/dissection"]'::jsonb, 3, 'A widened mediastinum following blunt chest trauma is a red-flag sign that warrants urgent evaluation for traumatic aortic injury.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 77, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'CT pulmonary angiography is the imaging investigation of choice to diagnose:', '["Pulmonary embolism", "Osteoarthritis", "Peptic ulcer disease", "Simple rib fracture"]'::jsonb, 0, 'CT pulmonary angiography directly visualises contrast-filled pulmonary arteries and is the standard imaging test to confirm or exclude pulmonary embolism.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 78, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Which imaging modality is generally first-line for rapidly diagnosing acute intracranial haemorrhage?', '["Plain X-ray of the skull", "CT scan", "Doppler flow study", "Ultrasound"]'::jsonb, 1, 'CT scanning is fast and widely available, making it the first-line imaging choice for suspected acute intracranial haemorrhage.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 79, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'A dosimeter badge worn by theatre staff is used to:', '["Measure cumulative radiation dose", "Check the staff member''s heart rate", "Measure the staff''s body temperature", "Identify staff names at the door"]'::jsonb, 0, 'Badges are checked regularly to ensure exposure stays within limits.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 80, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Barium contrast studies are absolutely contraindicated when there is suspicion of:', '["Mild gastritis", "Bowel perforation", "Simple constipation", "Uncomplicated reflux"]'::jsonb, 1, 'Barium leaking into the peritoneum through a perforation causes barium peritonitis and adhesions, which is life-threatening — water-soluble contrast is used instead if perforation is suspected.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 81, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Ultrasound imaging is preferred in pregnancy because it:', '["Uses low-dose X-rays that cannot harm the fetus", "Uses radioactive isotopes with a short half-life", "Uses a strong magnetic field and radio waves", "Uses sound waves, not ionising radiation"]'::jsonb, 3, 'Ultrasound is safe and widely available. It is used for FAST scans in trauma.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 82, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'An endotracheal tube tip on chest X-ray should ideally sit approximately how far above the carina?', '["10–12 cm above the carina", "At the level of the carina exactly", "3–5 cm above the carina", "In the right main bronchus"]'::jsonb, 2, 'The ETT tip should sit roughly 3–5 cm above the carina to avoid accidental right main bronchus intubation or extubation with neck movement.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 83, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'The main principle of radiation protection is ALARA, meaning:', '["Absorb Large Amounts Regularly", "As Low As Reasonably Achievable", "Always Leave All Radiation Alone", "All Levels Are Radiation Acceptable"]'::jsonb, 1, 'Time, distance and shielding reduce exposure.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 84, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'On a plain abdominal X-ray, multiple dilated bowel loops with air-fluid levels on an erect film are classic findings of:', '["Normal bowel gas pattern", "Gallstones", "Chronic constipation only", "Intestinal obstruction"]'::jsonb, 3, 'Dilated, gas-filled bowel loops with air-fluid levels on an erect film are the classic radiographic sign of mechanical bowel obstruction.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 85, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'An absolute contraindication to MRI scanning is:', '["A non-MRI-conditional cardiac pacemaker or ferromagnetic implant", "Pregnancy in the second trimester (with appropriate precautions)", "Recent blood test", "Mild claustrophobia"]'::jsonb, 0, 'Ferromagnetic implants or non-MRI-conditional devices such as certain pacemakers can be displaced or malfunction in the MRI''s strong magnetic field, making them absolute contraindications.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 86, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Ionic (High Osmolar) contrast media, compared to non-ionic (Low Osmolar) contrast media, are associated with:', '["Fewer side effects and higher cost", "More side effects but lower cost", "No side effects at any dose", "Identical side-effect profile and cost"]'::jsonb, 1, 'Ionic/HOCM agents dissociate into ions, have high osmolality, and cause more reactions, but are cheaper than non-ionic/LOCM agents such as iohexol.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 87, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Free air under the diaphragm on erect chest X-ray suggests:', '["Amoebic liver abscess", "Right lower lobe pneumonia", "Perforated hollow viscus", "Right-sided pleural effusion"]'::jsonb, 2, 'Recent laparotomy can also cause free air.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 88, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Free air visible under the diaphragm on an erect chest/abdominal X-ray most strongly suggests:', '["Chronic heart failure", "Pulmonary embolism", "Normal post-prandial bowel gas", "Perforation of a hollow viscus"]'::jsonb, 3, 'Pneumoperitoneum (free sub-diaphragmatic air) is a classic sign of a perforated hollow abdominal organ and represents a surgical emergency.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 89, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'In theatre, the radiographer''s role during cholangiography is to:', '["Give the anaesthetic and monitor the patient", "Count the swabs and instruments with the scrub nurse", "Perform the surgical part of the procedure", "Operate imaging and advise on radiation safety"]'::jsonb, 3, 'Clear communication between surgeon and radiographer reduces radiation exposure and delays.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 90, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Which of the following is classified as a positive (radio-opaque/white-appearing) contrast agent?', '["Carbon dioxide", "Room air", "Barium", "Vacuum/no contrast"]'::jsonb, 2, 'Positive contrast agents such as iodine-based media and barium are dense and appear white/opaque on imaging, unlike negative agents such as air or CO2 which appear dark/lucent.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 91, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Radiation exposure risk to staff is lowest when:', '["Holding the patient''s limb in position during the shot", "Standing on the image intensifier (receptor) side", "Standing on the X-ray tube side of the C-arm", "Standing close to the beam to watch the screen"]'::jsonb, 1, 'Scatter is greatest on the tube side.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 92, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Negative contrast agents (e.g. air, carbon dioxide) appear on imaging as:', '["Identical in appearance to iodinated contrast", "Only visible on MRI, never on X-ray", "Dark and lucent", "Dense and white (opaque)"]'::jsonb, 2, 'Negative contrast agents such as air or CO2 have low density and appear dark/lucent on radiographic images, the opposite of positive agents like barium or iodine.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 93, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Patient had head trauma and you suspect that he has intracranial haemorrhage, Which of following modalities you will choose?', '["CT", "X-ray with contrast", "Conventional x-ray", "MRI"]'::jsonb, 0, 'CT is the imaging modality of choice for detecting acute intracranial haemorrhage.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 94, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'On an abdominal X-ray, a ''coffee bean sign'' is classically associated with which condition?', '["Simple constipation", "Sigmoid volvulus", "Normal bowel gas pattern", "Gallstones"]'::jsonb, 1, 'The ''coffee bean sign'' describes the characteristic dilated, twisted loop of bowel seen on abdominal X-ray in sigmoid volvulus.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 95, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'Oral iodinated contrast carries a specific risk if aspirated, namely:', '["Permanent loss of taste", "Immediate cardiac arrest", "Pulmonary oedema and chemical pneumonitis", "No risk at all — it is inert if aspirated"]'::jsonb, 2, 'Aspiration of oral iodinated contrast can cause pulmonary oedema and chemical pneumonitis, which is why aspiration risk must be assessed before oral contrast is given.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 96, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'The first-line imaging investigation in suspected acute stroke is:', '["Non-contrast CT head", "Abdominal ultrasound", "MRI with contrast", "Chest X-ray"]'::jsonb, 0, 'Non-contrast CT head is performed urgently in suspected stroke primarily to exclude haemorrhage before considering thrombolytic therapy.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 97, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'The three main principles of radiation protection are:', '["Heat, cold and water", "Speed, noise and light", "Cost, staff and space", "Time, distance and shielding"]'::jsonb, 3, 'Minimise time, maximise distance and use shielding.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 98, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'CT scanning is preferred over plain X-ray in head injury because it shows:', '["Only disease of the sinuses", "Intracranial bleeding and swelling", "Only fractures of the skull", "Only wounds of the scalp"]'::jsonb, 1, 'Non-contrast CT is the first investigation.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 99, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'In a tension pneumothorax on X-ray, the trachea deviates to the:', '["Same (ipsilateral) side", "Opposite (contralateral) side", "Remains exactly midline", "Cannot be assessed on X-ray"]'::jsonb, 1, 'Trapped air under pressure pushes the mediastinal structures, including the trachea, away from the affected side.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(1, 100, 'Anaesthesia Nursing Mock — Day 3 Morning (Nov 2026)', 'NAP 412 · Applied Physics, Chemistry & Radiology', 'The ALARA principle in radiologic imaging stands for:', '["A Legal Requirement for All Radiographs", "As Low As Reasonably Achievable (radiation exposure)", "Always Limit Additional Radiographic Access", "Any Level Achievable with Repeated Attempts"]'::jsonb, 1, 'ALARA (''As Low As Reasonably Achievable'') guides minimising radiation exposure to patients and staff while still obtaining diagnostically useful images.', 'NAP 412 · Applied Physics, Chemistry & Radiology'),
(2, 1, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Tranexamic acid reduces surgical bleeding by:', '["Activating platelets directly", "Replacing clotting factors", "Inhibiting fibrinolysis (clot breakdown)", "Constricting all arteries"]'::jsonb, 2, 'It is given in major trauma, orthopaedics and PPH.', 'NAP 413 · Applied Pharmacology I'),
(2, 2, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A patient with Torsades de Pointes is prescribed magnesium sulfate. Which ECG change confirms efficacy?', '["Resolution of U waves", "Absent P waves", "Shortened QT interval", "Narrowed QRS complex"]'::jsonb, 2, 'Magnesium shortens the QT interval, treating Torsades. U waves are associated with hypokalemia.', 'NAP 413 · Applied Pharmacology I'),
(2, 3, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'which of this is a narcotic analgesics', '[".Morphine", "Acetamophine", "Ibuprofen", "Halothen"]'::jsonb, 0, 'Morphine is a classic narcotic (opioid) analgesic.', 'NAP 413 · Applied Pharmacology I'),
(2, 4, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The antidote used to reverse benzodiazepine sedation is:', '["Naloxone", "Flumazenil", "Acetylcysteine", "Protamine sulphate"]'::jsonb, 1, 'Flumazenil blocks the same receptor benzodiazepines act on, though caution is needed in dependent patients.', 'NAP 413 · Applied Pharmacology I'),
(2, 5, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'What is the treatment of choice for hypovolemic shock?', '["Administer a vasopressor", "Replace fluids intravenously as quickly as possible", "Have the patient drink a large bottle of water", "Give epinephrine"]'::jsonb, 1, 'Rapid IV fluid replacement is the priority treatment for hypovolaemic shock.', 'NAP 413 · Applied Pharmacology I'),
(2, 6, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The specific antidote for opioid overdose (e.g. morphine, fentanyl) is:', '["Naloxone", "Flumazenil", "N-acetylcysteine", "Activated charcoal"]'::jsonb, 0, 'Naloxone is a competitive opioid receptor antagonist used to reverse opioid-induced respiratory depression.', 'NAP 413 · Applied Pharmacology I'),
(2, 7, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Vitamin K is used to reverse excessive anticoagulation from which drug?', '["Heparin", "Enoxaparin", "Aspirin", "Warfarin"]'::jsonb, 3, 'Vitamin K restores synthesis of clotting factors suppressed by warfarin, reversing its anticoagulant effect (though onset is slower than with prothrombin complex concentrate).', 'NAP 413 · Applied Pharmacology I'),
(2, 8, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A patient with atrial fibrillation is started on amiodarone. The nurse should monitor for:', '["Pulmonary fibrosis", "Diarrhea", "Hypertension", "Hypoglycemia"]'::jsonb, 0, 'Amiodarone can cause pulmonary fibrosis, thyroid dysfunction, and liver toxicity.', 'NAP 413 · Applied Pharmacology I'),
(2, 9, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Isoflurane differs from sevoflurane because it is:', '["More pungent and less suitable for gas induction", "Non-pungent and ideal for children''s induction", "Given intravenously", "Not a volatile agent"]'::jsonb, 0, 'Isoflurane is used mainly for maintenance.', 'NAP 413 · Applied Pharmacology I'),
(2, 10, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Phenylephrine given for spinal hypotension in caesarean section commonly causes:', '["Reflex bradycardia", "Bronchospasm", "Hyperglycaemia", "Marked tachycardia"]'::jsonb, 0, 'It is a pure alpha-1 agonist.', 'NAP 413 · Applied Pharmacology I'),
(2, 11, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Gastric lavage is contraindicated in which of the following situations?', '["Corrosive/acid ingestion", "General sedative overdose within 1 hour", "Barbiturate overdose while still conscious", "Within 2 hours of a large tablet overdose"]'::jsonb, 0, 'Passing a tube for a corrosive substance risks further damage to the oesophagus and stomach.', 'NAP 413 · Applied Pharmacology I'),
(2, 12, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The concentration of inhalational anaesthetic at which a patient responds purposefully to verbal command during emergence is referred to as:', '["MAC95", "MAC-BAR", "MAC-awake", "Blood-gas MAC"]'::jsonb, 2, 'MAC-awake, typically about 0.3-0.5 of standard MAC, is the concentration at which patients begin to respond to verbal commands as anaesthesia lightens.', 'NAP 413 · Applied Pharmacology I'),
(2, 13, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'This is known as the fright and flight hormone', '["Oxytocin", "Vasopressin", "Epinephrine", "Insulin"]'::jsonb, 2, 'Epinephrine (adrenaline) is known as the fight-or-flight hormone.', 'NAP 413 · Applied Pharmacology I'),
(2, 14, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Ketamine is useful for induction in a shocked asthmatic patient because it:', '["Has no effect on airway reflexes", "Reverses opioid-induced breathing problems", "Maintains blood pressure and causes bronchodilation", "Lowers BP and causes bronchospasm"]'::jsonb, 2, 'It is an NMDA antagonist. Emergence reactions are common in adults.', 'NAP 413 · Applied Pharmacology I'),
(2, 15, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'If blood glucose levels are low, then epinephrine and glucagon hormones are secreted to stimulate the conversion of glycogen to glucose. This process is called', '["Glycogenesis", "Glucose uptake", "Glycogenolysis", "Glucose formation"]'::jsonb, 2, 'Breaking glycogen back down into glucose is glycogenolysis.', 'NAP 413 · Applied Pharmacology I'),
(2, 16, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Atropine is used in anaesthesia to:', '["Raise the blood glucose before surgery", "Reverse opioid respiratory depression", "Induce sleep at the start of anaesthesia", "Treat bradycardia and dry secretions"]'::jsonb, 3, 'Atropine is an anticholinergic (muscarinic blocker). Side effects include dry mouth, tachycardia, urinary retention, blurred vision and confusion in the elderly.', 'NAP 413 · Applied Pharmacology I'),
(2, 17, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A drug with a narrow therapeutic index is one where:', '["The drug can only be given by the oral route", "The drug can never cause toxicity in practice", "The effective dose is far below the toxic dose", "The toxic dose is close to the effective dose"]'::jsonb, 3, 'Examples are digoxin, gentamicin, lithium, phenytoin and warfarin. Blood levels or effects must be monitored closely.', 'NAP 413 · Applied Pharmacology I'),
(2, 18, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'To provide rapid pain relief in the ICU, which of the following routes of opioid administration is most appropriate?', '["Sublingual", "Intradermal", "Intraspinal", "Intravenous"]'::jsonb, 3, 'IV opioids act within minutes and can be titrated, which makes IV the route for rapid pain relief in ICU.', 'NAP 413 · Applied Pharmacology I'),
(2, 19, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Which of the following is not a weak opioid?', '["Hydromorphone", "Hydrocodone", "Codeine", "Tramadol"]'::jsonb, 0, 'Hydromorphone is a strong (not weak) opioid, unlike codeine, tramadol, and hydrocodone.', 'NAP 413 · Applied Pharmacology I'),
(2, 20, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Atropine is useful at induction in children mainly to:', '["Reverse muscle relaxants", "Deepen anaesthesia", "Prevent vomiting", "Prevent bradycardia and reduce secretions"]'::jsonb, 3, 'Children''s cardiac output depends heavily on heart rate.', 'NAP 413 · Applied Pharmacology I'),
(2, 21, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Amide local anaesthetics are metabolised mainly in the:', '["Lungs", "Plasma by cholinesterase", "Kidneys unchanged", "Liver"]'::jsonb, 3, 'Ester local anaesthetics are broken down by plasma cholinesterase.', 'NAP 413 · Applied Pharmacology I'),
(2, 22, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The Hormone produced by adrenal glands that arouses the body is ...', '["Adrenaline", "Prolactin", "Insulin", "Glucagon"]'::jsonb, 0, 'Adrenaline (epinephrine) is the adrenal hormone that arouses the fight-or-flight response.', 'NAP 413 · Applied Pharmacology I'),
(2, 23, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Midazolam''s effects can be reversed with:', '["Neostigmine", "Naloxone", "Sugammadex", "Flumazenil"]'::jsonb, 3, 'Flumazenil is shorter-acting than many benzodiazepines; resedation can occur.', 'NAP 413 · Applied Pharmacology I'),
(2, 24, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Hypnotic medications differ from anxiolytics primarily in their main clinical purpose, which is to:', '["Lower blood pressure", "Induce and maintain sleep", "Treat bacterial infections", "Reduce anxiety during waking hours specifically"]'::jsonb, 1, 'While some drug classes overlap, hypnotics are specifically used to induce/maintain sleep, distinct from anxiolytics'' primary anti-anxiety purpose.', 'NAP 413 · Applied Pharmacology I'),
(2, 25, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Dexamethasone given at induction is used mainly to:', '["Prevent PONV and reduce swelling", "Reverse muscle relaxation", "Replace thyroid hormone", "Treat hypoglycaemia"]'::jsonb, 0, 'It may raise blood glucose in diabetics.', 'NAP 413 · Applied Pharmacology I'),
(2, 26, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A commonly prescribed mast cell stabilizer used for asthma is:', '["Theophylline", "Cromolyn sodium", "Budesonide", "Albuterol"]'::jsonb, 1, 'Cromolyn sodium is a classic mast cell stabiliser used in asthma prevention.', 'NAP 413 · Applied Pharmacology I'),
(2, 27, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Flushing and rash on the upper body during IV vancomycin is best managed by:', '["Giving it as an IV push", "Slowing the infusion rate", "Doubling the dose", "Stopping all antibiotics permanently"]'::jsonb, 1, 'This ''red man'' reaction is histamine release, not true allergy. Also monitor levels and kidney function.', 'NAP 413 · Applied Pharmacology I'),
(2, 28, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A thyroidectomy patient complains of palpitations and anxiety preoperatively. The nurse should administer:', '["Propanolol", "Adrenaline", "Dopamine", "Morphine"]'::jsonb, 0, 'Propranolol controls the adrenaline-driven symptoms (palpitations, anxiety, tremor) of residual hyperthyroidism.', 'NAP 413 · Applied Pharmacology I'),
(2, 29, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'A patient with status epilepticus is receiving midazolam. Which reversal agent is on standby?', '["Flumazenil", "Protamine", "Naloxone", "Glucagon"]'::jsonb, 0, 'Flumazenil reverses benzodiazepines like midazolam.', 'NAP 413 · Applied Pharmacology I'),
(2, 30, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Which antibiotic acts as a protein synthesis inhibitor?', '["Trimethoprim", "Penicillin", "Tetracycline", "Cefotaxime"]'::jsonb, 2, 'Tetracyclines bind the 30S ribosomal subunit and block protein synthesis. Penicillins and cephalosporins act on the cell wall; trimethoprim blocks folate.', 'NAP 413 · Applied Pharmacology I'),
(2, 31, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Which of the following is a thrombolytic agent?', '["Clexane (enoxaparin)", "Heparin", "Streptokinase", "Warfarin sodium"]'::jsonb, 2, 'Streptokinase (like alteplase) is a thrombolytic that dissolves clots. Heparin, enoxaparin (Clexane) and warfarin are anticoagulants that only stop clots growing.', 'NAP 413 · Applied Pharmacology I'),
(2, 32, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Which volatile anaesthetic agent is most associated with sensitizing the myocardium to catecholamines, predisposing to arrhythmias, particularly if epinephrine is administered concurrently?', '["Halothane", "Nitrous oxide", "Desflurane", "Sevoflurane"]'::jsonb, 0, 'Halothane sensitizes the myocardium to circulating catecholamines more than other modern volatile agents, increasing the risk of ventricular arrhythmias when epinephrine-containing solutions are used.', 'NAP 413 · Applied Pharmacology I'),
(2, 33, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The second-line drug of choice for status epilepticus, given as an IV loading dose, is:', '["Salbutamol", "Lorazepam", "Phenytoin", "Adrenaline"]'::jsonb, 2, 'Phenytoin is used when first-line benzodiazepines alone haven''t stopped the seizure.', 'NAP 413 · Applied Pharmacology I'),
(2, 34, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'The first-line vasopressor of choice in septic shock is:', '["Vasopressin", "Dopamine", "Norepinephrine", "Adrenaline"]'::jsonb, 2, 'Norepinephrine is the preferred first-choice drug to raise blood pressure in septic shock.', 'NAP 413 · Applied Pharmacology I'),
(2, 35, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 413 · Applied Pharmacology I', 'Ephedrine raises blood pressure by:', '["Increasing blood volume", "Blocking acetylcholine at the heart", "Pure alpha-1 vasoconstriction with reflex bradycardia", "Direct and indirect sympathomimetic action, raising heart rate and contractility"]'::jsonb, 3, 'It is useful for spinal hypotension with a low heart rate.', 'NAP 413 · Applied Pharmacology I'),
(2, 36, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'With an antimicrobial soap, the WHO-recommended duration of a surgical hand scrub is usually:', '["2–5 minutes, as the manufacturer recommends", "10–15 minutes for every scrub of the day", "At least 20 minutes for the first case only", "15–30 seconds, as for an alcohol hand rub"]'::jsonb, 0, 'Long scrubs (10 minutes or more) give no extra benefit and damage skin. Alcohol-based surgical hand rubs are an alternative, applied for the time the product specifies.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 37, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The best description of healing by primary intention is:', '["The wound is closed after several days of being left open", "The wound is left open and heals slowly from the base by granulation tissue", "The wound is left open to fill with granulation tissue", "Wound edges are brought together, healing quickly with minimal scar"]'::jsonb, 3, 'Secondary intention is used for infected wounds; tertiary is delayed primary closure.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 38, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient is at risk for developing post-operative urinary retention. What nursing interventions can help prevent or manage urinary retention in the post-operative period?', '["Encourage the patient to void regularly, even if they do not feel the urge", "Monitor intake and output closely", "Assist the patient with toileting as needed", "Use bladder ultrasound or intermittent catheterization as necessary"]'::jsonb, 0, 'Encouraging regular voiding attempts helps prevent postoperative urinary retention from progressing.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 39, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Refeeding syndrome after starting feeds in a malnourished ICU patient causes:', '["High blood glucose with normal electrolytes", "High calcium, high sodium and high chloride", "High phosphate, high potassium and high urea", "Low phosphate, low potassium and low magnesium"]'::jsonb, 3, 'Start feeds slowly, give thiamine and monitor electrolytes.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 40, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A Deaver retractor is used mainly in:', '["Dental extraction, to hold the cheek", "Deep abdominal surgery to hold back organs", "Hand surgery, to hold back the skin edges of small wounds", "Eye surgery, to hold the eyelid open"]'::jsonb, 1, 'Self-retaining retractors (e.g. Balfour) free the assistant''s hands.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 41, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A PACU nurse sees that the patient''s oxygen tubing has become disconnected. This shows the importance of:', '["Leaving the bay unattended for short periods", "Regular checks of equipment as well as the patient", "Turning off the alarms to reduce noise", "Using less monitoring on each patient so that alarms are rare"]'::jsonb, 1, 'Look at the patient, then the monitor.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 42, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'In PACU, a patient''s blood pressure is 220/120 mmHg. Before giving drugs, the nurse should check:', '["The patient''s usual diet at home", "The time of the next theatre case", "Pain, full bladder, hypoxia and a correct reading", "The surgeon''s name and grade, and the theatre the patient came from"]'::jsonb, 2, 'Use a correctly sized cuff.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 43, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The tourniquet inflation time must be recorded and the surgeon told:', '["Never, as it is the anaesthetist''s job", "At regular intervals, e.g. each hour of inflation", "Only if the patient complains of pain", "Only when the operation ends and the tourniquet has been fully released"]'::jsonb, 1, 'Prolonged ischaemia damages nerves and muscle.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 44, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'When preparing skin around a stoma or the perineum, these ''dirty'' areas are cleaned:', '["Never, as these areas cannot be cleaned", "First, before the surrounding skin, so that they are cleaned properly", "Last, after the cleaner surrounding area", "First, before the surrounding skin"]'::jsonb, 2, 'This avoids carrying organisms onto clean skin.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 45, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Ephedrine is best used with one of the following condition', '["Local infiltration", "Peripheral vasodilatation", "Hypertension", "General Anaestheisa"]'::jsonb, 1, 'Ephedrine, an indirect-acting sympathomimetic, is useful for anaesthesia-related hypotension from peripheral vasodilatation, raising both heart rate and blood pressure.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 46, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Irrigation fluids used in a body cavity should be:', '["At room temperature from the store", "Boiling hot to sterilise the cavity", "Warmed to body temperature", "Chilled to reduce bleeding"]'::jsonb, 2, 'Cold fluids worsen hypothermia.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 47, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Oxygen therapy toxicity is most associated with:', '["Nebulised bronchodilator therapy", "Use of room air only", "Prolonged exposure to high concentrations of oxygen", "Short-term, low-concentration oxygen use"]'::jsonb, 2, 'Prolonged high-concentration oxygen therapy can cause oxygen toxicity, contributing to lung injury — hence the principle of using the lowest effective FiO2.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 48, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'An LMA may be removed in PACU when the patient:', '["Is asleep with the cuff fully deflated", "Is still deeply unconscious with no reflexes", "Starts to vomit with the cuff still inflated", "Is awake and can open the mouth on command"]'::jsonb, 3, 'Removal technique varies; follow unit policy.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 49, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A day-case patient being discharged home after general anaesthesia should:', '["Go home alone by public transport after an hour", "Go home with a responsible adult and not drive for 24–48 h", "Sign important legal documents the same evening", "Drive themselves home if they feel fully alert after one hour in recovery"]'::jsonb, 1, 'Give written instructions and a contact number.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 50, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A post-operative patient who has not passed urine for 8 hours with lower abdominal discomfort most likely has:', '["Acute renal failure in all cases", "Urinary retention", "Fluid overload", "Normal post-operative state"]'::jsonb, 1, 'Bladder scanning confirms retention. Causes include opioids, spinal anaesthesia, anticholinergics and pain. Catheterisation may be needed.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 51, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient develops pneumonia postoperatively due to decreased lung function. What is the priority nursing intervention?', '["Encouraging fluid intake", "Administering pain medication", "Providing emotional support", "Positioning for optimal breathing"]'::jsonb, 3, 'Positioning that optimises lung expansion (e.g. semi- to high-Fowler''s) supports oxygenation and secretion clearance in postoperative pneumonia.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 52, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The most reliable immediate confirmation that an endotracheal tube is in the trachea is:', '["No gurgling heard over the stomach on inflation", "Misting seen inside the tube on expiration", "A sustained capnography trace over several breaths", "The chest rising on one side with each breath"]'::jsonb, 2, 'Misting and chest movement can occur with oesophageal intubation. A consistent end-tidal CO2 trace over at least six breaths is the gold standard bedside confirmation.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 53, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Post-operative cognitive dysfunction (POCD) is:', '["A decline in memory and thinking after surgery, mostly in older people", "A type of deep wound infection after major surgery", "A normal and expected finding in all young children", "A problem caused only by local anaesthetic drugs given during the surgery"]'::jsonb, 0, 'It may last weeks to months.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 54, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A needle holder should grasp a curved needle:', '["In the middle of the suture thread", "At the swaged end of the needle only", "One-third to halfway from the swaged end", "At the very point of the needle, for the firmest grip"]'::jsonb, 2, 'Holding the point blunts it; holding the swage can break it.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 55, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Post-thyroidectomy tingling around the mouth and fingers, with carpopedal spasm, suggests:', '["Hypokalaemia from post-operative vomiting", "Hypercalcaemia from excess PTH release", "Thyroid storm from handling of the gland", "Hypocalcaemia from parathyroid injury"]'::jsonb, 3, 'Chvostek''s and Trousseau''s signs confirm hypocalcaemia. Treatment is IV calcium gluconate.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 56, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Nerve damage can occur as a complication of surgery. Which assessment finding should the nurse prioritize in a patient with suspected nerve damage?', '["Abdominal pain", "Sensory changes", "Increased heart rate", "Elevated temperature"]'::jsonb, 1, 'Sensory changes (numbness, altered sensation) are a key assessment finding suggesting postoperative nerve injury.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 57, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Consent for surgery in an unconscious adult needing emergency life-saving surgery:', '["Requires a court order every time, even in emergency", "Must be signed by the most senior nurse on duty before surgery can begin", "Must wait until the patient wakes up and can sign", "Is not needed; treat in the patient''s best interests"]'::jsonb, 3, 'Document the reasons; inform relatives where possible.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 58, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The most effective active warming method during surgery is usually:', '["Raising the room temperature to 35 °C", "A forced-air warming blanket", "Extra cotton sheets only", "Warm fluids given orally"]'::jsonb, 1, 'Also warm IV and irrigation fluids and keep the patient covered.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 59, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient in PACU is drowsy, with pinpoint pupils and respiratory rate of 7 per minute. The most likely cause is:', '["Hypoglycaemia", "Local anaesthetic toxicity", "Hypovolaemic shock", "Opioid overdose"]'::jsonb, 3, 'The nurse supports the airway, gives oxygen and assists breathing as needed, calls the anaesthetist and prepares naloxone.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 60, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Implants used in surgery are recorded in the patient''s notes mainly to:', '["Allow tracing of the device if it is recalled", "Count the instruments at the end of the case", "Calculate the surgeon''s fee for the case", "Check that the steriliser cycle worked correctly for that tray"]'::jsonb, 0, 'Record the batch/lot and serial numbers.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 61, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A pregnancy test before elective surgery in women of childbearing age is done mainly because:', '["Anaesthesia, X-rays and surgery may harm an unknown pregnancy", "It is needed to calculate all the anaesthetic drug doses", "Pregnancy shortens the operation and the recovery time needed afterwards", "It replaces the need for a separate signed consent form"]'::jsonb, 0, 'Follow local policy and respect patient choice.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 62, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The patient is asked to empty the bladder before going to theatre mainly to:', '["Shorten the fasting time before surgery", "Help the patient to sleep before surgery", "Allow the urine to be sent for culture", "Prevent bladder injury and incontinence"]'::jsonb, 3, 'A catheter may be inserted for long procedures.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 63, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A patient is on a neuromuscular blocking agent. The nurse knows that this medication is used to:', '["Cause muscle paralysis", "Relieve pain", "Induce sedation", "Decrease anxiety"]'::jsonb, 0, 'Neuromuscular blocking agents are used to paralyze the patient''s muscles. They do not have a sedative or analgesic effect. The patient may still be conscious and able to feel pain and anxiety, so they must be used in conjunction with a sedative and an analgesic.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 64, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The ''sterile cockpit'' or no-interruption rule in theatre applies particularly during:', '["Counts, Time Out and critical steps of the operation", "Ordering supplies from the store", "Lunch breaks and rest periods", "Cleaning between cases and restocking of the theatre"]'::jsonb, 0, 'Distractions cause errors in counts and checks.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 65, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'For skin preparation of a clean abdominal incision, the antiseptic is applied:', '["From the outer edges inward, finishing at the incision site", "From the periphery inward toward the incision", "In random strokes over the whole abdomen", "From the incision site outward toward the periphery"]'::jsonb, 3, 'Do not return to the clean centre with a used swab.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 66, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'A safety strap for a supine patient on the operating table is placed:', '["Tightly across the chest, under the arms", "Directly over the abdomen, at the waist", "About 5 cm above the knees, loosely over a blanket", "Over both ankles, fastened firmly so that the legs cannot move at all"]'::jsonb, 2, 'It must not restrict circulation or breathing.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 67, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'The Bromage score is used to assess:', '["Postoperative nausea and vomiting", "Level of sedation after anaesthesia", "Motor block of the legs after spinal or epidural", "Pain intensity at rest and on movement on a 0–10 scale"]'::jsonb, 2, 'Increasing motor block on an epidural can signal a haematoma.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 68, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Which precaution is most important in reducing the risk of anaesthetic death related to a difficult or failed airway?', '["Avoiding pre-oxygenation so that the procedure is completed faster", "Thorough airway assessment and a ready difficult airway plan and equipment", "Proceeding with induction without any airway assessment to save time", "Relying only on the surgeon''s assessment of the patient''s airway"]'::jsonb, 1, 'Systematic pre-anaesthetic airway assessment, along with a clear failed-airway algorithm and immediately available difficult airway equipment, significantly reduces the risk of catastrophic hypoxia from failed intubation.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 69, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Postoperative shivering is most commonly related to:', '["Excessive analgesia", "Hyperglycaemia", "Intraoperative hypothermia", "Overhydration"]'::jsonb, 2, 'Shivering after anaesthesia is most often a thermoregulatory response to intraoperative heat loss and residual anaesthetic effects on thermoregulation.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 70, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'NAP 414 · Nursing Anaesthesia Practice', 'Adrenaline is added to local anaesthetic solutions mainly to:', '["Treat or prevent any allergy the patient may have to the drug", "Speed up the onset of general anaesthesia given at the same time", "Cause vasoconstriction, prolonging the block and reducing absorption", "Reduce the pH of the solution so that it works faster in tissues"]'::jsonb, 2, 'Adrenaline-containing solutions have traditionally been avoided in end-artery areas such as digits and penis because of the risk of ischaemia.', 'NAP 414 · Nursing Anaesthesia Practice'),
(2, 71, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Fasciitis is commonly characterised as which type of infection?', '["Mono-microbial", "Entity microbial", "Gram-negative microbial", "Polymicrobial"]'::jsonb, 3, 'Necrotising fasciitis type I, the commonest form, is polymicrobial (mixed aerobes and anaerobes). Type II is usually group A strep.', 'GSM 410 · Applied Microbiology'),
(2, 72, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The disease COVID-19 was officially named on:', '["31 December 2019", "11 February 2020", "13 February 2020", "13 March 2020"]'::jsonb, 1, 'WHO named the disease "COVID-19" on 11 February 2020.', 'GSM 410 · Applied Microbiology'),
(2, 73, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Prions, as causes of CJD, are:', '["Bacteria", "Abnormal infectious proteins", "Fungi that grow in damp areas", "Viruses"]'::jsonb, 1, 'They resist normal sterilisation.', 'GSM 410 · Applied Microbiology'),
(2, 74, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The main purpose of a biological indicator in sterilisation monitoring is to:', '["Test the electrical safety of the steriliser itself", "Show only that the pack went through the steriliser", "Confirm the cycle killed highly resistant spores", "Measure the humidity of the theatre and the store"]'::jsonb, 2, 'Chemical indicators (e.g. indicator tape) only show exposure to the process. Biological indicators contain living spores and give direct evidence of lethality; they are used routinely and with every load containing implants.', 'GSM 410 · Applied Microbiology'),
(2, 75, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The most appropriate statements regarding necrotizing soft tissue infection include:', '["Type 2 infection is likely to be polymicrobial.", "Type 2 necrotizing soft tissue infection is associated with toxic shock syndrome.", "Type 1 infection accounts for 80--90% of cases and is likely to occur in the perineal and trunk areas.", "Type 4 infection is likely to occur in immunocompetent patients."]'::jsonb, 0, 'Type 2 necrotizing soft tissue infection is often polymicrobial or specifically streptococcal, matching the classic teaching.', 'GSM 410 · Applied Microbiology'),
(2, 76, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A surgical site infection is defined as one occurring within how long of an operation without an implant?', '["1 year", "30 days", "48 hours", "7 days"]'::jsonb, 1, 'SSI surveillance: within 30 days of surgery, or up to 90 days (or 1 year in older definitions) when an implant such as a joint prosthesis or mesh is left in place.', 'GSM 410 · Applied Microbiology'),
(2, 77, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A viral infection cannot be treated by:', '["Vaccination for prevention", "Antiviral drugs", "Supportive care", "Antibacterial antibiotics"]'::jsonb, 3, 'Antibiotics do not kill viruses.', 'GSM 410 · Applied Microbiology'),
(2, 78, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Standard precautions differ from transmission-based precautions in that standard precautions:', '["Are only used for confirmed infections", "Replace the need for PPE entirely", "Are optional depending on staff preference", "Apply to ALL patients, all the time"]'::jsonb, 3, 'Standard precautions form the baseline of care for every patient, regardless of known infection status.', 'GSM 410 · Applied Microbiology'),
(2, 79, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The most effective way to stop the spread of droplet infections such as influenza is:', '["N95 respirator for all visitors", "Closing all windows", "A surgical mask within 1–2 metres and hand hygiene", "An N95 respirator for every visitor, with the windows kept closed"]'::jsonb, 2, 'Droplets travel short distances.', 'GSM 410 · Applied Microbiology'),
(2, 80, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The correct order for doffing (removing) PPE is:', '["Hand hygiene → Gloves → Gown → Mask → Goggles", "Mask → Gown → Goggles → Gloves → Hand hygiene", "Goggles → Mask → Gloves → Gown", "Gloves → Goggles → Gown → Mask → Hand hygiene"]'::jsonb, 3, 'The most contaminated item (gloves) is removed first, and hand hygiene is performed last, after everything else is off.', 'GSM 410 · Applied Microbiology'),
(2, 81, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Hand hygiene breaks the chain of infection mainly at the:', '["Reservoir", "Agent, by killing the organism", "Susceptible host", "Mode of transmission"]'::jsonb, 3, 'Hands are the main route of spread in hospitals.', 'GSM 410 · Applied Microbiology'),
(2, 82, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The anaerobic organism that commonly causes infection after colorectal surgery, and is treated with metronidazole, is:', '["Bacteroides fragilis", "Staphylococcus epidermidis", "Streptococcus pyogenes", "Pseudomonas aeruginosa"]'::jsonb, 0, 'Bacteroides fragilis is a Gram-negative anaerobe of the large bowel. Prophylaxis for colorectal surgery therefore covers both Gram-negatives (e.g. cefuroxime or gentamicin) and anaerobes (metronidazole).', 'GSM 410 · Applied Microbiology'),
(2, 83, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The correct order for donning personal protective equipment before entering an isolation room is:', '["Hand hygiene, gown, mask, goggles, gloves", "Gloves, mask, gown, hand hygiene", "Mask, gloves, gown, hand hygiene", "Goggles, gown, hand hygiene, gloves, mask"]'::jsonb, 0, 'Standard donning sequence is hand hygiene first, then gown, mask, goggles/eye protection, and gloves last, ensuring the most contamination-prone items (gloves) go on last.', 'GSM 410 · Applied Microbiology'),
(2, 84, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'After a needlestick injury from an infected source, the bloodborne virus with the HIGHEST transmission risk is:', '["Hepatitis C (in anyone exposed)", "Hepatitis A (in a non-immune person)", "Hepatitis B (in a non-immune person)", "HIV (human immunodeficiency virus)"]'::jsonb, 2, 'Approximate risks after percutaneous exposure: hepatitis B up to 30% (non-immune), hepatitis C about 2%, HIV about 0.3%. All theatre staff should be vaccinated against hepatitis B and their antibody response checked.', 'GSM 410 · Applied Microbiology'),
(2, 85, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A ''dirty'' surgical wound carries an infection risk of approximately:', '["10%", "40–50%", "20–30%", "1–5%"]'::jsonb, 1, 'Dirty wounds (with established infection or gross contamination) carry the highest baseline infection risk of the four wound classification categories.', 'GSM 410 · Applied Microbiology'),
(2, 86, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Pseudomonas aeruginosa is a particular concern in:', '["Normal gut flora only", "Burns and ventilated patients", "Healthy intact skin of young adults", "Clean dry wounds"]'::jsonb, 1, 'It thrives in moist environments.', 'GSM 410 · Applied Microbiology'),
(2, 87, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Mr John, a post-operative patient in ICU, developed a severe fever 4 days after surgery. This is typical of:', '["Secondary infection", "Normal surgical process", "Malnutrition", "Primary infection"]'::jsonb, 0, 'A fever several days after surgery suggests a newly acquired (secondary or nosocomial) infection such as wound infection, pneumonia or UTI.', 'GSM 410 · Applied Microbiology'),
(2, 88, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The order for putting on (donning) PPE is usually:', '["Gown, mask, goggles, gloves", "Mask, gloves, gown, goggles", "Gloves, goggles, mask, gown", "Goggles, gloves, gown, mask"]'::jsonb, 0, 'Doffing is gloves, goggles, gown, mask, then hand hygiene.', 'GSM 410 · Applied Microbiology'),
(2, 89, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'An endotoxin is:', '["A protein secreted by Gram-positive bacteria only", "Part of the cell wall of Gram-negative bacteria", "A type of antibiotic", "A toxin made only by viruses"]'::jsonb, 1, 'It triggers septic shock.', 'GSM 410 · Applied Microbiology'),
(2, 90, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A patient on a mechanical ventilator develops new fever, purulent secretions, and a new infiltrate on chest X-ray after 4 days of ventilation. This presentation is most consistent with:', '["Simple atelectasis with no infection", "Normal expected findings on a ventilator", "Pulmonary embolism", "Ventilator-Associated Pneumonia (VAP)"]'::jsonb, 3, 'New fever, purulent secretions and a new infiltrate after several days of mechanical ventilation are classic diagnostic features of VAP.', 'GSM 410 · Applied Microbiology'),
(2, 91, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A key nursing intervention to prevent line sepsis is:', '["Reusing syringes on the same patient''s line", "Scrubbing the hub before every access", "Changing dressings only when they fall off", "Leaving three-way taps open and uncapped"]'::jsonb, 1, 'Use 2% chlorhexidine in alcohol for 15 seconds.', 'GSM 410 · Applied Microbiology'),
(2, 92, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Barrier nursing, as classically defined, aims to:', '["Protect the patient from others", "Only apply to surgical patients", "Protect others from the patient", "Have no protective purpose"]'::jsonb, 2, 'Standard barrier nursing (source isolation) is about preventing an infected patient from spreading disease to others.', 'GSM 410 · Applied Microbiology'),
(2, 93, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A burn wound produces green-blue pus with a sweet, grape-like smell. The most likely organism is:', '["Staphylococcus aureus", "Candida albicans", "Clostridium perfringens", "Pseudomonas aeruginosa"]'::jsonb, 3, 'Pseudomonas produces blue-green pigments (pyocyanin) and is common in burns, moist environments and ventilated patients. It is often resistant to many antibiotics.', 'GSM 410 · Applied Microbiology'),
(2, 94, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The correct hand-washing technique should take about:', '["5 minutes", "40–60 seconds", "About 5 minutes, scrubbing to the elbows", "5 seconds"]'::jsonb, 1, 'Alcohol rub takes about 20–30 seconds.', 'GSM 410 · Applied Microbiology'),
(2, 95, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Two days after minor surgery, a patient has severe wound pain out of proportion to its appearance, rapidly spreading redness, dusky skin, crepitus and septic shock. The most important action is:', '["Urgent surgical debridement plus broad-spectrum IV antibiotics", "Wait for blood culture results before starting any treatment", "Oral antibiotics, wound swab, and review in the clinic in 48 hours", "Warm compresses, elevation and simple analgesia, then observation"]'::jsonb, 0, 'Necrotising fasciitis (often Group A Streptococcus or polymicrobial) spreads along fascial planes. Mortality falls with early radical debridement; antibiotics alone are not enough.', 'GSM 410 · Applied Microbiology'),
(2, 96, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Eye protection (goggles or a face shield) is required for theatre staff when:', '["Only when the patient is known to have HIV infection", "Splashing or spraying of blood or body fluid is likely", "Never, because a surgical mask protects the face fully", "Only during orthopaedic operations that use power tools"]'::jsonb, 1, 'Standard precautions require PPE chosen according to the expected exposure: mucous membranes of the eyes, nose and mouth must be protected whenever splashes are possible (e.g. irrigation, vascular, orthopaedic and obstetric surgery).', 'GSM 410 · Applied Microbiology'),
(2, 97, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'An antiseptic differs from a disinfectant because an antiseptic is:', '["Used only on floors", "Used on living tissue such as skin", "Stronger than all disinfectants", "Always a sterilant that kills spores on instruments"]'::jsonb, 1, 'Disinfectants are for inanimate objects.', 'GSM 410 · Applied Microbiology'),
(2, 98, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'Droplet precautions, typically requiring a surgical mask, are appropriate for a patient with:', '["MRSA colonisation", "Active pulmonary tuberculosis", "C. difficile infection", "Influenza"]'::jsonb, 3, 'Droplet precautions with a surgical mask are used for pathogens spread via larger respiratory droplets over short distances, such as influenza.', 'GSM 410 · Applied Microbiology'),
(2, 99, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'The VAP bundle includes head-of-bed elevation of:', '["90 degrees at all times", "30–45 degrees", "Flat (0 degrees) to rest the lungs", "5–10 degrees only"]'::jsonb, 1, 'Other elements: daily sedation hold and SBT, oral care with chlorhexidine, subglottic suction, DVT and ulcer prophylaxis.', 'GSM 410 · Applied Microbiology'),
(2, 100, 'Anaesthesia Nursing Mock — Day 3 Afternoon (Nov 2026)', 'GSM 410 · Applied Microbiology', 'A suspected Lassa fever patient needing surgery requires:', '["Surgery in the general ward", "Standard gloves only, as for any other surgical patient", "Full PPE, isolation and strict sharps safety", "No special precautions"]'::jsonb, 2, 'Person-to-person spread through blood and body fluids occurs.', 'GSM 410 · Applied Microbiology'),
(3, 1, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Effective communication with an anxious patient involves:', '["Avoiding eye contact to reduce tension", "Using medical jargon to sound expert", "Interrupting the patient to save time", "Active listening, empathy and clear explanation"]'::jsonb, 3, 'Nonverbal cues are important.', 'GSB 410 · Applied Behavioural Science'),
(3, 2, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A client has multiple identified nursing diagnoses. Which method is commonly used to prioritize these diagnoses?', '["The order in which they were identified during assessment", "Alphabetical order of the diagnostic labels", "Client''s personal preference alone, without clinical judgment", "Maslow''s Hierarchy of Needs, addressing physiological and safety needs first"]'::jsonb, 3, 'Maslow''s Hierarchy of Needs is a common framework for prioritizing nursing diagnoses, with physiological and safety needs typically addressed first.', 'GSB 410 · Applied Behavioural Science'),
(3, 3, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A nurse is organizing assessment data using Maslow''s Hierarchy of Needs. Which finding would be prioritized at the most basic (foundational) level?', '["Client is worried about returning to work", "Client has an oxygen saturation of 84% on room air", "Client expresses low self-esteem", "Client reports feeling isolated from friends"]'::jsonb, 1, 'Maslow''s hierarchy places physiological needs, such as oxygenation, at the foundational level, taking priority over psychosocial or self-esteem needs.', 'GSB 410 · Applied Behavioural Science'),
(3, 4, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Projection as a defence mechanism means:', '["Returning to childish behaviour", "Refusing to accept reality", "Attributing one''s own unacceptable feelings to others", "Turning feelings into physical symptoms"]'::jsonb, 2, 'E.g. an angry patient accusing the nurse of being angry.', 'GSB 410 · Applied Behavioural Science'),
(3, 5, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Which of the following best describes the ''regulator'' coping subsystem in Roy''s model?', '["A subsystem exclusive to the role-function adaptive mode", "A subsystem that responds automatically through neural, chemical, and endocrine processes", "A subsystem used only for spiritual coping", "A subsystem that processes information through cognitive-emotive channels such as perception and learning"]'::jsonb, 1, 'The regulator subsystem is the automatic coping process involving neural, chemical, and endocrine responses, such as the physiological stress response.', 'GSB 410 · Applied Behavioural Science'),
(3, 6, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A client who was previously the primary breadwinner expresses distress about being unable to return to work after a spinal cord injury and struggles with the loss of that role within the family. This is best classified under which Roy adaptive mode?', '["Role function mode", "Interdependence mode", "Physiological-physical mode", "Self-concept/group identity mode"]'::jsonb, 0, 'The role function mode addresses the roles a person occupies in society (e.g., worker, parent) and how the person adapts to changes in those roles, such as loss of the breadwinner role after injury.', 'GSB 410 · Applied Behavioural Science'),
(3, 7, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A defence mechanism in which a patient refuses to accept a diagnosis is:', '["Projection", "Denial", "Regression", "Sublimation"]'::jsonb, 1, 'Nurses allow time and provide support.', 'GSB 410 · Applied Behavioural Science'),
(3, 8, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Rationalisation is:', '["Forgetting a painful event", "Refusing to believe a diagnosis", "Acting like a child", "Giving logical-sounding excuses for unacceptable behaviour"]'::jsonb, 3, 'It protects self-esteem.', 'GSB 410 · Applied Behavioural Science'),
(3, 9, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Feedback shows that caring is a key element of practice. Which theorist best supports this concept?', '["Watson", "Rogers", "Maslow", "Erikson"]'::jsonb, 0, 'Jean Watson''s Theory of Human Caring makes caring central to nursing.', 'GSB 410 · Applied Behavioural Science'),
(3, 10, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A nurse is caring for a client who is in acute respiratory distress and also expressing anxiety about an upcoming diagnostic test. Using Maslow''s hierarchy to prioritize care, the nurse should address which need FIRST?', '["The client''s need for self-esteem and a sense of accomplishment", "The client''s need for social interaction with family", "The client''s anxiety about the diagnostic test (safety/psychological need)", "The client''s airway and oxygenation status (physiological need)"]'::jsonb, 3, 'Physiological needs, including oxygenation, take priority over higher-level needs such as psychological safety or emotional reassurance according to Maslow''s hierarchy, making airway/breathing the first priority.', 'GSB 410 · Applied Behavioural Science'),
(3, 11, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'One of the following is called the positive stress.', '["Eustress", "Anxiety", "Worries", "Happiness"]'::jsonb, 0, 'Eustress is the recognised term for positive, beneficial stress.', 'GSB 410 · Applied Behavioural Science'),
(3, 12, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Which of the following is included among Henderson''s 14 basic needs?', '["Progress through the regulator and cognator coping subsystems", "Avoid dangers in the environment and avoid injuring others", "Maintain the normal line of defense against stressors", "Achieve pandimensional integrality with the environment"]'::jsonb, 1, '''Avoid dangers in the environment and avoid injuring others'' is one of Henderson''s 14 components of basic nursing care, addressing safety needs.', 'GSB 410 · Applied Behavioural Science'),
(3, 13, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Following successful treatment of a stressor reaction, a nurse focuses on rehabilitation and helping the client readapt to promote stability and prevent future reoccurrence of the stressor. This reflects which of Neuman''s prevention levels?', '["Tertiary prevention", "Reconstitutive prevention only, unrelated to Neuman''s model", "Primary prevention", "Secondary prevention"]'::jsonb, 0, 'Tertiary prevention occurs after secondary prevention/treatment and focuses on readaptation, reconstitution, and maintaining stability to prevent further regression or recurrence of the stressor reaction.', 'GSB 410 · Applied Behavioural Science'),
(3, 14, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Culture influences perioperative care because:', '["Culture has no effect on care in the theatre", "All patients share exactly the same beliefs", "Only the surgeons'' culture affects patient care", "Beliefs about illness, blood, pain and modesty differ"]'::jsonb, 3, 'Culturally sensitive care improves trust.', 'GSB 410 · Applied Behavioural Science'),
(3, 15, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Abraham Maslow''s hierarchy of needs is typically depicted as a pyramid with which level at the very base, representing the most fundamental needs?', '["Love and belonging needs", "Self-actualization needs", "Physiological needs", "Safety and security needs"]'::jsonb, 2, 'Physiological needs, such as oxygen, food, water, and elimination, form the base of Maslow''s pyramid because they must generally be met first to sustain life before higher-level needs can be addressed.', 'GSB 410 · Applied Behavioural Science'),
(3, 16, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'Preoperative anxiety can be reduced by:', '["Withholding information about surgery", "Information, listening and reassurance", "Ignoring the patient until induction", "Shouting instructions so they are heard"]'::jsonb, 1, 'Anxiety increases pain and anaesthetic requirements.', 'GSB 410 · Applied Behavioural Science'),
(3, 17, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A nurse is caring for four clients simultaneously. Which client''s need should the nurse prioritize FIRST according to Maslow''s hierarchy of needs?', '["A client with an oxygen saturation of 84% on room air", "A client expressing embarrassment about needing help with bathing", "A client requesting a chaplain visit for spiritual support", "A client worried about being discharged without family support"]'::jsonb, 0, 'A critically low oxygen saturation represents an urgent physiological need (oxygenation) that takes priority over safety, love/belonging, and esteem needs according to Maslow''s hierarchy.', 'GSB 410 · Applied Behavioural Science'),
(3, 18, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A client who is newly diagnosed with a colostomy expresses distress, saying, ''I don''t feel like myself anymore; I feel disfigured.'' This response falls primarily within which of Roy''s adaptive modes?', '["Physiological-physical mode", "Role function mode", "Self-concept/group identity mode", "Interdependence mode"]'::jsonb, 2, 'Concerns about body image and personal identity following a change such as a colostomy fall within the self-concept/group identity mode, which addresses the person''s beliefs and feelings about the self, including body image.', 'GSB 410 · Applied Behavioural Science'),
(3, 19, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A client recovering from a mastectomy tells the nurse, ''I''m worried my husband won''t find me attractive anymore and that we''ll grow apart.'' This concern is most directly related to which level of Maslow''s hierarchy?', '["Self-actualization needs", "Safety and security needs", "Physiological needs", "Love and belonging needs"]'::jsonb, 3, 'Concerns about intimacy and connectedness within a significant relationship correspond to the love and belonging level of Maslow''s hierarchy.', 'GSB 410 · Applied Behavioural Science'),
(3, 20, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSB 410 · Applied Behavioural Science', 'A nurse initiates prompt treatment after a client develops symptoms of a stressor reaction, aiming to reduce the effects and strengthen internal lines of resistance. This corresponds to which Neuman prevention level?', '["Preventive maintenance", "Tertiary prevention", "Secondary prevention", "Primary prevention"]'::jsonb, 2, 'Secondary prevention focuses on treatment of symptoms after a stressor has invaded the system and produced a reaction, aiming to strengthen the internal lines of resistance and restore stability.', 'GSB 410 · Applied Behavioural Science'),
(3, 21, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Fundamental research is otherwise called:', '["Action research", "Survey", "Pilot study", "Pure research"]'::jsonb, 3, 'Fundamental research is also called pure or basic research.', 'GSR 410 · Research Methodology & Statistics'),
(3, 22, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A patient''s marital status (single, married, divorced, widowed) recorded in a research questionnaire is measured on which scale?', '["Ordinal", "Nominal", "Ratio", "Interval"]'::jsonb, 1, 'Marital status categories have no inherent numeric order, making this a nominal-level variable.', 'GSR 410 · Research Methodology & Statistics'),
(3, 23, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The guiding clinical principle for choosing between enteral and parenteral nutrition in a critically ill patient is best summarized as:', '["Parenteral nutrition should always be used first regardless of GI function", "\"If the gut works, use it\" — enteral nutrition is preferred whenever the GI tract is functional", "Oral intake should always be attempted before any tube feeding is considered, regardless of aspiration risk", "Enteral and parenteral nutrition are equally preferred with no clinical rationale for choosing one over the other"]'::jsonb, 1, 'The core principle of nutrition support is that enteral feeding should be used whenever the gastrointestinal tract is functional, because it is safer, more physiologic, and less costly than parenteral nutrition.', 'GSR 410 · Research Methodology & Statistics'),
(3, 24, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Drawing conclusions without bias or value judgement is called:', '["Specificity", "Objectivity", "Facts", "Values"]'::jsonb, 1, 'Objectivity means drawing conclusions from evidence without bias or value judgement.', 'GSR 410 · Research Methodology & Statistics'),
(3, 25, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The recommended bedside check of nasogastric tube position before feeding is:', '["The ''whoosh'' test with air and a stethoscope", "Patient comfort with no coughing", "Placing the tube end in water to look for bubbles", "Aspirate pH of 5.5 or below"]'::jsonb, 3, 'If pH is above 5.5 or no aspirate is obtained, confirm with X-ray. The whoosh test is unreliable.', 'GSR 410 · Research Methodology & Statistics'),
(3, 26, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A patient receiving a lipid-containing TPN infusion should have which laboratory value monitored to detect a potential metabolic complication of the lipid emulsion?', '["Serum bilirubin level only", "Serum uric acid level", "Serum triglyceride level", "Serum amylase level only"]'::jsonb, 2, 'Lipid emulsions can cause hypertriglyceridemia, particularly if infused too rapidly, so serum triglyceride levels should be monitored periodically during lipid administration.', 'GSR 410 · Research Methodology & Statistics'),
(3, 27, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Which of the following is one of the skills specifically used during the evaluation phase?', '["Billing insurance", "Interviewing", "Performing surgery", "Prescribing medication"]'::jsonb, 1, 'Talking with the patient (interviewing) is one of the direct ways a nurse gathers information to judge how care is progressing.', 'GSR 410 · Research Methodology & Statistics'),
(3, 28, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Which of the following is an example of a common ERROR in writing a nursing diagnosis, in which the statement is written as a medical diagnosis rather than a nursing diagnosis?', '["\"Activity Intolerance related to fatigue\"", "\"Acute Pain related to tissue trauma\"", "\"Diagnosis: Congestive Heart Failure\"", "\"Deficient Fluid Volume related to vomiting\""]'::jsonb, 2, '"Congestive Heart Failure" is a medical diagnosis naming a disease process, not a nursing diagnosis describing the client''s response, and should not be used as one.', 'GSR 410 · Research Methodology & Statistics'),
(3, 29, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A hypothesis that describes a relationship between two variables is:', '["Relational", "Tentative", "Descriptive", "Causal"]'::jsonb, 0, 'A relational (associative) hypothesis states that two variables are related, without claiming cause.', 'GSR 410 · Research Methodology & Statistics'),
(3, 30, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The characteristic of scientific research that roots findings in objective reality is:', '["Systematisation", "Control", "Generalisation", "Empiricism"]'::jsonb, 3, 'Empiricism means knowledge is grounded in objective observation, evidence gathered through the senses.', 'GSR 410 · Research Methodology & Statistics'),
(3, 31, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A sickle cell disease patient''s haemoglobin genotype is:', '["HbAC", "HbAA", "HbAS", "HbSS"]'::jsonb, 3, 'HbAS is the carrier (trait).', 'GSR 410 · Research Methodology & Statistics'),
(3, 32, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The less variation an instrument produces in repeated measurements of an attribute, the higher its:', '["Reliability", "Validity", "Relativity", "Sensitivity"]'::jsonb, 0, 'Reliability is consistency: less variation on repeated measurement means higher reliability.', 'GSR 410 · Research Methodology & Statistics'),
(3, 33, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A correlational design differs from a true experimental design by:', '["Studying cause-and-effect relationships", "Using a multidirectional approach", "Studying variables in an atypical setting", "Studying associations between phenomena"]'::jsonb, 3, 'Correlational designs look for associations between variables without manipulating them, so they cannot prove causation.', 'GSR 410 · Research Methodology & Statistics'),
(3, 34, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A literature review that is organized by grouping studies according to recurring topics or findings, rather than simply listing them chronologically, is following a', '["Thematic organization approach", "Approach that ignores all study findings", "Purely alphabetical listing with no analysis", "Random and unstructured approach"]'::jsonb, 0, 'Thematic organization groups related studies and findings around key concepts or themes, producing a more coherent and analytical review than a simple list.', 'GSR 410 · Research Methodology & Statistics'),
(3, 35, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Your patient has developed a low-grade fever and states that she has felt very tired lately. You interpret these findings as indicating which stage of infection?', '["Prodromal stage", "Convalescent period", "Full stage of illness", "Incubation period"]'::jsonb, 0, 'Low-grade fever and fatigue before specific symptoms appear describe the prodromal stage of infection.', 'GSR 410 · Research Methodology & Statistics'),
(3, 36, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Which variable is NOT manipulated by the researcher but measured as the outcome?', '["Extraneous variable", "Internal variable", "Independent variable", "Dependent variable"]'::jsonb, 3, 'The dependent variable is measured, not manipulated. It is the outcome or effect.', 'GSR 410 · Research Methodology & Statistics'),
(3, 37, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The concrete observable events which represent the abstract concepts or constructs are called', '["Proposition", "Data", "Variable", "Sample"]'::jsonb, 2, 'Concrete, observable representations of abstract concepts are variables.', 'GSR 410 · Research Methodology & Statistics'),
(3, 38, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The independent variable refers to:', '["The variable manipulated or varied by the researcher", "The aim of an experiment", "The variable that shows the effect of the manipulation", "A variable used only in the control group"]'::jsonb, 0, 'The independent variable is the one the researcher manipulates. The dependent variable shows its effect.', 'GSR 410 · Research Methodology & Statistics'),
(3, 39, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Sterilisation by steam (autoclave) at 134 °C usually takes:', '["3 minutes holding time", "30 seconds holding time", "1 hour holding time", "24 hours holding time"]'::jsonb, 0, '121 °C requires 15 minutes holding time.', 'GSR 410 · Research Methodology & Statistics'),
(3, 40, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A nurse assesses a client''s exercise habits, activities of daily living, and any factors that interfere with the client''s desired activity level (such as dyspnea or chest pain). This corresponds to which Gordon functional health pattern?', '["Self-perception-self-concept pattern", "Activity-exercise pattern", "Sleep-rest pattern", "Nutritional-metabolic pattern"]'::jsonb, 1, 'The activity-exercise pattern describes the client''s pattern of exercise, activity, leisure, and recreation, as well as factors like cardiovascular or respiratory symptoms that limit desired activity.', 'GSR 410 · Research Methodology & Statistics'),
(3, 41, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'In research, the term "universe" refers to the:', '["Research instrument", "Entire population", "Study setting", "Sample"]'::jsonb, 1, 'The "universe" is the whole population: all the units of interest.', 'GSR 410 · Research Methodology & Statistics'),
(3, 42, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Repositioning an immobile client every 2 hours to prevent pressure injury, without a physician''s order, is an example of which type of nursing intervention?', '["Interdependent intervention", "Dependent intervention", "Independent intervention", "Delegated medical intervention"]'::jsonb, 2, 'Turning and repositioning to prevent pressure injury is within independent nursing practice and does not require a physician''s order.', 'GSR 410 · Research Methodology & Statistics'),
(3, 43, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'The lowest measurement scale in statistics is the:', '["Nominal scale", "Ordinal scale", "Interval scale", "Ratio scale"]'::jsonb, 0, 'The levels of measurement, lowest to highest, are nominal, ordinal, interval and ratio.', 'GSR 410 · Research Methodology & Statistics'),
(3, 44, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'Which is one of the WHO ''five moments'' for hand hygiene?', '["Only after removing gloves at home", "Before entering the hospital car park", "Only at the start of the shift", "Before an aseptic or clean procedure"]'::jsonb, 3, 'The others: before touching a patient, after body fluid exposure, after touching a patient and after touching their surroundings.', 'GSR 410 · Research Methodology & Statistics'),
(3, 45, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSR 410 · Research Methodology & Statistics', 'A nurse reviewing an electronic health record to identify a client''s past surgical history and allergies is using which source and method of data collection?', '["Primary source, observation method", "Primary source, interview method", "Secondary source, physical examination method", "Secondary source, record review method"]'::jsonb, 3, 'The health record is a secondary source, and reviewing it is the record review method of data collection.', 'GSR 410 · Research Methodology & Statistics'),
(3, 46, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'The core legal/professional principle behind nursing documentation is best summarised as:', '["''If it wasn''t documented, it wasn''t done''", "Only negative events need to be documented", "Documentation is optional if care was given correctly", "Documentation can be completed weeks later without issue"]'::jsonb, 0, 'Accurate, timely documentation is a nurse''s primary legal protection — undocumented care is very difficult to prove was ever given.', 'GSE 410 · Ethico-Legal Issues'),
(3, 47, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'In nursing ethics, the principle of Justice specifically requires:', '["Prioritising patients by social status", "Ignoring resource limitations entirely", "Giving preferential treatment to paying patients", "Treating all patients equally regardless of background"]'::jsonb, 3, 'Justice in nursing means a patient''s background should never influence the quality of care they receive.', 'GSE 410 · Ethico-Legal Issues'),
(3, 48, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'The Nuremberg Code primarily established the requirement for:', '["Voluntary consent and subject welfare", "Peer review of all studies", "Statistical significance testing", "Government funding approval"]'::jsonb, 0, 'This code emerged after WWII specifically to ensure research subjects freely agree to participate and that their welfare is protected.', 'GSE 410 · Ethico-Legal Issues'),
(3, 49, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A nurse is asked by a patient''s employer for information about the patient''s diagnosis and prognosis. The nurse''s appropriate response is to:', '["Decline to share any information without the patient''s explicit, documented consent, citing confidentiality obligations", "Share information only if the employer insists strongly", "Provide the requested information immediately, since the employer is asking on the patient''s behalf", "Share only positive information"]'::jsonb, 0, 'Patient confidentiality obligations mean health information cannot be disclosed to third parties, including employers, without the patient''s explicit informed consent.', 'GSE 410 · Ethico-Legal Issues'),
(3, 50, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A failure in professional duty, practice or skill that leads to injury or harm to the patient is termed as-', '["Negligence", "Misunderstanding", "Malpractice", "Crime"]'::jsonb, 2, 'A professional failure causing patient harm is malpractice.', 'GSE 410 · Ethico-Legal Issues'),
(3, 51, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A nurse who makes a drug error should:', '["Hide the error to avoid trouble with the manager", "Report at once, protect the patient and document it", "Blame the pharmacist or the prescribing doctor", "Wait to see whether the patient complains first"]'::jsonb, 1, 'Honesty is a professional and ethical duty.', 'GSE 410 · Ethico-Legal Issues'),
(3, 52, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', '''Non-maleficence'' as an ethical principle means:', '["Being honest with the patient", "Being fair and just to all patients", "Doing no harm to the patient", "Doing good for the patient"]'::jsonb, 2, 'Non-maleficence is the principle of ''first, do no harm'' — avoiding actions that could injure the patient.', 'GSE 410 · Ethico-Legal Issues'),
(3, 53, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Which principle is an obligation to tell the truth and not lie or deceive the patient?', '["Justice", "Confidentiality", "Fidelity", "Veracity"]'::jsonb, 3, 'Veracity is the duty to tell the truth. Fidelity means keeping promises.', 'GSE 410 · Ethico-Legal Issues'),
(3, 54, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'The physician instructed the Nurse in the ICU to run a slow code as the family was not agreed for DNR. The approach used here to help the patient and family in the end of life is termed as:', '["Life Support", "Spiritual support", "Ethical Dilemma", "DNR"]'::jsonb, 2, 'Performing a deliberately less-aggressive code due to family/DNR disagreement is a classic ethical dilemma in critical care.', 'GSE 410 · Ethico-Legal Issues'),
(3, 55, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', '__________ is the technique in which each worker is supervised by eight supervisors.', '["Functional foremanship", "Unity of action", "Centralisation", "Simplification of work"]'::jsonb, 0, 'Taylor''s functional foremanship has each worker supervised by eight specialist foremen.', 'GSE 410 · Ethico-Legal Issues'),
(3, 56, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Whistleblowing is:', '["Gossiping about colleagues with other staff", "Leaking patient data to the press", "Raising concerns about unsafe or illegal practice", "Making personal complaints about workload"]'::jsonb, 2, 'Nurses have a duty to raise concerns to protect patients.', 'GSE 410 · Ethico-Legal Issues'),
(3, 57, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A minor''s consent for surgery in Nigeria is usually given by:', '["Any adult relative", "The child alone", "Parent or legal guardian", "The ward nurse"]'::jsonb, 2, 'Emergency exceptions apply when delay would cause serious harm.', 'GSE 410 · Ethico-Legal Issues'),
(3, 58, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Which ethical principle is demonstrated by respecting a competent patient''s informed refusal of treatment?', '["Fidelity", "Autonomy", "Justice", "Beneficence"]'::jsonb, 1, 'Respecting a competent patient''s informed refusal of treatment reflects the ethical principle of autonomy.', 'GSE 410 · Ethico-Legal Issues'),
(3, 59, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A family disagrees with a DNR order for a patient with metastatic lung cancer. The nurse involves:', '["Social services", "Ethics committee", "Risk management", "Hospital security"]'::jsonb, 1, 'An ethics committee helps resolve conflicts about goals of care.', 'GSE 410 · Ethico-Legal Issues'),
(3, 60, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', '''Veracity'' as an ethical principle in nursing means:', '["Avoiding harm", "Truthfulness and honesty with patients", "Loyalty and faithfulness to commitments", "Fairness in resource distribution"]'::jsonb, 1, 'Veracity is the ethical duty to be truthful and honest with patients about their condition and care.', 'GSE 410 · Ethico-Legal Issues'),
(3, 61, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Confidentiality may be breached when:', '["A journalist asks for details of a famous patient", "Required by law or to protect others from serious harm", "A relative or friend asks casually about the patient", "Never, under any circumstances whatsoever"]'::jsonb, 1, 'Only necessary information is disclosed.', 'GSE 410 · Ethico-Legal Issues'),
(3, 62, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'The ''Beneficence'' principle obligates the nurse to:', '["Simply avoid causing harm", "Distribute resources equally", "Actively act in ways that promote the patient''s wellbeing and best interests", "Always follow the patient''s exact instructions regardless of clinical judgement"]'::jsonb, 2, 'Beneficence goes beyond avoiding harm (non-maleficence) — it obligates the nurse to actively act for the patient''s good and wellbeing.', 'GSE 410 · Ethico-Legal Issues'),
(3, 63, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Informed consent for surgery must be obtained by:', '["The patient''s relative, if the patient is anxious", "The theatre porter, when collecting the patient", "The surgeon doing the procedure, or a competent delegate", "The scrub nurse, after the patient arrives in theatre"]'::jsonb, 2, 'The nurse may witness the signature and should report if the patient seems uninformed.', 'GSE 410 · Ethico-Legal Issues'),
(3, 64, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Which is NOT a barrier to communication in health care?', '["Lack of trust", "Semantic distortion", "Teamwork", "Poor listening"]'::jsonb, 2, 'Poor listening, semantic distortion and lack of trust are barriers to communication. Teamwork helps it.', 'GSE 410 · Ethico-Legal Issues'),
(3, 65, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Negligence requires proof of:', '["A complaint alone from the family", "Harm alone, whatever the cause", "An error alone, even with no harm", "Duty, breach, causation and harm"]'::jsonb, 3, 'Retained swabs are classic examples of negligence.', 'GSE 410 · Ethico-Legal Issues'),
(3, 66, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A nurse is caring for a patient who is refusing treatment for his condition. The patient''s family is pressuring the nurse to persuade the patient to accept treatment. What should the nurse do?', '["Respect the patient''s autonomy and allow him refuse treatment.", "Consult with another nurse to determine the best course of action", "Seek a court order to force the patient to accept treatment", "Persuade the patient to accept treatment to satisfy the family''s wishes"]'::jsonb, 0, 'Respecting patient autonomy means allowing a competent patient to refuse treatment, even under family pressure.', 'GSE 410 · Ethico-Legal Issues'),
(3, 67, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'The Belmont Report''s 3 core ethical principles are:', '["Consent, Privacy, Fairness", "Honesty, Accuracy, Transparency", "Autonomy, Beneficence, Justice", "Safety, Dignity, Respect"]'::jsonb, 2, 'These three principles form the foundational framework most modern research ethics guidelines build upon.', 'GSE 410 · Ethico-Legal Issues'),
(3, 68, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'In staffing function, which one of the following groups of managers is involved?', '["All managers", "Only top managers", "Only middle managers", "Only human resource managers"]'::jsonb, 0, 'Every manager takes part in staffing: selecting, training and appraising their own staff.', 'GSE 410 · Ethico-Legal Issues'),
(3, 69, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'Vicarious liability means:', '["No one is responsible when an employee makes an error", "An employer is responsible for employees'' acts at work", "Patients are responsible for the acts of their nurses", "A nurse is responsible for every act of the doctor"]'::jsonb, 1, 'Nurses remain personally accountable for their practice.', 'GSE 410 · Ethico-Legal Issues'),
(3, 70, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSE 410 · Ethico-Legal Issues', 'A nurse experiences moral distress when a terminally ill patient receives aggressive CPR. This arises from:', '["Legal obligation", "Inadequate staffing", "Ethical dilemma", "Personal values conflict"]'::jsonb, 3, 'Moral distress occurs when actions conflict with personal ethics.', 'GSE 410 · Ethico-Legal Issues'),
(3, 71, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'One of these is not a function of the Mouse', '["to type text", "to display a menu", "to open or execute a program", "to move the mouse cursor"]'::jsonb, 0, 'A mouse moves the cursor, opens programs and shows menus. Typing text is done with the keyboard.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 72, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Which of the following is an example of an Internet browser?', '["Internet Navigator", "Notepad", "Internet Explorer", "Microsoft Word"]'::jsonb, 2, 'A web browser (Internet Explorer, Chrome, Firefox, Edge) is software for viewing websites. Notepad and Word are text editors.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 73, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Multi-processing in a computer file system refers to the ability to:', '["Process only one task at a time, strictly in sequence", "Handle multiple processing tasks concurrently", "Never process data outside business hours", "Only work with a single connected device"]'::jsonb, 1, 'Multi-processing capability allows a system to handle several processing tasks concurrently, improving efficiency for multi-user hospital systems.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 74, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A computer network within one hospital building is a:', '["Personal Area Network", "Wide Area Network (WAN)", "Local Area Network (LAN)", "Metropolitan Area Network"]'::jsonb, 2, 'A WAN links hospitals across cities; the internet is the largest WAN.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 75, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A barcode scanning system in theatre helps to:', '["Replace the need for swab and instrument counts", "Avoid any documentation of implants and drugs", "Increase errors by adding extra steps to the work", "Track instruments, implants and drugs accurately"]'::jsonb, 3, 'It supports traceability.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 76, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Identify the five main components of a computer system in their order?', '["CPU, Memory, System bus, Input, Output", "Memory, Video card, Monitor, Software, Hardware", "CPU, CD-ROM, Mouse, Keyboard, Sound card", "Modem, Keyboard, Word Processor, Printer, Screen"]'::jsonb, 0, 'CPU, memory, system bus, input, and output are the five core computer system components.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 77, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'What does it mean to double click?', '["to press the right mouse button twice in quick succession.", "to press the left mouse button twice in quick succession.", "to press the left mouse button once", "to press the right mouse button once"]'::jsonb, 1, 'Double-clicking means pressing the left mouse button twice in quick succession.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 78, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A CT scanner and ultrasound machine are examples of ICT in:', '["Administration only", "Treatment only", "Diagnosis", "Nursing education only"]'::jsonb, 2, 'Monitoring devices (oximeter, cardiac monitor) and treatment devices (infusion pumps, radiotherapy) are other categories.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 79, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Protecting electronic access to client data primarily relies on which of the following measures?', '["Disabling all data backups", "Printing all records to avoid computer use entirely", "Leaving all records openly accessible to any staff member for convenience", "User authentication (passwords/logins), access controls and audit trails"]'::jsonb, 3, 'Controlled access via authentication, role-based permissions and audit trails is a core safeguard for protecting confidential electronic client data.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 80, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'The first generation of computers used:', '["Integrated circuits", "Vacuum tubes", "Microprocessors", "Transistors"]'::jsonb, 1, 'Second: transistors; third: integrated circuits; fourth: microprocessors; fifth: artificial intelligence.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 81, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A nurse is teaching a group of nursing students about the history of computers. Which generation of computers is characterized by the use of vacuum tubes?', '["First Generation", "Fourth Generation", "Second Generation", "Third Generation"]'::jsonb, 0, 'The First Generation of computers, from 1940 to 1956, were characterized by the use of bulky and energy-inefficient vacuum tubes for circuitry. Second Generation computers used transistors, Third Generation used integrated circuits, and Fourth Generation used microprocessors.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 82, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'RAM in a computer stands for:', '["Read And Modify", "Random Access Memory", "Rapid Access Machine", "Remote Access Module"]'::jsonb, 1, 'RAM is temporary working memory.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 83, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'Which one is application software?', '["Avast Antivirus", "Microsoft Word", "Windows XP", "Android 11"]'::jsonb, 1, 'Microsoft Word is application software. Windows and Android are operating systems; antivirus is utility software.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 84, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'ONE OF THESE IS NOT AN ADVANTAGE OF COMPUTER FILES', '["It is relatively easy to reproduce or duplicate", "it is hard to use", "it offers faster access and retrieval of data", "it enhances security of data if proper precautions are taken"]'::jsonb, 1, 'Computer files are easy to copy, secure when protected, and quick to retrieve. Being "hard to use" is not an advantage.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 85, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'GSC 410 · ICT & Nursing Informatics', 'A nurse is explaining the units of data to a patient. The smallest unit of data in a computer is a:', '["Megabyte", "Bit", "Byte", "Kilobyte"]'::jsonb, 1, 'A bit (binary digit) is the most basic unit of information in computing and is a one or a zero. A byte is a group of 8 bits. The other options are larger units of data.', 'GSC 410 · ICT & Nursing Informatics'),
(3, 86, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Use of English & Communication', 'Choose the correct preposition: ''The patient complained ___ severe pain.''', '["for", "with", "at", "of"]'::jsonb, 3, 'We complain of symptoms and about situations.', 'Use of English & Communication'),
(3, 87, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Use of English & Communication', 'The suffix ''-ectomy'' means:', '["Inflammation", "Surgical removal", "Repair", "Surgical opening"]'::jsonb, 1, '''-otomy'' means incision; ''-itis'' means inflammation; ''-plasty'' means repair.', 'Use of English & Communication'),
(3, 88, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Use of English & Communication', 'Choose the sentence written in the correct tense for a nursing record of past care:', '["The patient turns at 14:00 yesterday.", "The patient will be turned at 14:00 yesterday.", "The patient was turned at 14:00.", "The patient is turn at 14:00."]'::jsonb, 2, 'Records describe care already given in the past tense.', 'Use of English & Communication'),
(3, 89, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Use of English & Communication', 'The abbreviation ''NPO'' in a medical order means:', '["Nurse patient order", "Normal post-operative", "Nothing by mouth", "No pain observed"]'::jsonb, 2, 'From Latin ''nil per os''.', 'Use of English & Communication'),
(3, 90, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Use of English & Communication', 'The word ''post-operative'' means:', '["Without surgery", "During surgery", "Before surgery", "After surgery"]'::jsonb, 3, '''Pre'' means before and ''intra'' means during.', 'Use of English & Communication'),
(3, 91, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Use of English & Communication', 'Choose the word closest in meaning to ''deteriorate'':', '["Stabilise", "Recover", "Worsen", "Improve"]'::jsonb, 2, 'Accurate vocabulary is needed for clear clinical reports.', 'Use of English & Communication'),
(3, 92, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Use of English & Communication', 'The suffix ''-otomy'' means:', '["Cutting into", "Surgical removal", "Making a permanent opening", "Repair"]'::jsonb, 0, 'E.g. laparotomy, tracheotomy.', 'Use of English & Communication'),
(3, 93, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Use of English & Communication', 'The plural of ''bacterium'' is:', '["Bacteriums", "Bacterias", "Bacteria", "Bacterie"]'::jsonb, 2, 'Similar: datum/data, medium/media.', 'Use of English & Communication'),
(3, 94, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Entrepreneurship', 'Marketing mix (4Ps) includes product, price, place and:', '["Promotion", "Profit", "Planning", "People only"]'::jsonb, 0, 'Services often add people, process and physical evidence.', 'Entrepreneurship'),
(3, 95, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Entrepreneurship', 'Capital refers to:', '["Only the profit made at the end of the year", "Taxes paid to the government each year", "Only the salaries paid to the staff", "Money and assets used to run a business"]'::jsonb, 3, 'Sources include savings, loans and grants.', 'Entrepreneurship'),
(3, 96, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Entrepreneurship', 'Fixed costs are costs that:', '["Are always zero for a small business", "Are optional and can be stopped at will", "Do not change with output, such as rent", "Change directly with the level of output"]'::jsonb, 2, 'Variable costs, e.g. consumables, change with output.', 'Entrepreneurship'),
(3, 97, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Entrepreneurship', 'Entrepreneurship in nursing refers to:', '["Providing only bedside care, without any business role", "Working only in government hospitals on a fixed salary", "Avoiding innovation and keeping to routine practice", "Nurses creating and running services that meet health needs"]'::jsonb, 3, 'Examples include home care agencies, health consultancy and training centres.', 'Entrepreneurship'),
(3, 98, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Entrepreneurship', 'Cash flow problems in a business occur when:', '["The business has no costs", "All customers pay in advance", "Profit is very high", "Money coming in is less than money going out at a given time"]'::jsonb, 3, 'Even profitable businesses can fail from poor cash flow.', 'Entrepreneurship'),
(3, 99, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Entrepreneurship', 'Ethical business practice for a nurse entrepreneur includes:', '["Honest advertising and following professional standards", "Ignoring patient confidentiality", "Making false health claims", "Avoiding registration"]'::jsonb, 0, 'The Nursing and Midwifery Council''s code still applies.', 'Entrepreneurship'),
(3, 100, 'Anaesthesia Nursing Mock — Day 3 Night (Nov 2026)', 'Entrepreneurship', 'Innovation in perioperative nursing could include:', '["A better system for tracking theatre instruments", "Refusing to use any new technology in theatre", "Doing every task the same way as in the past", "Avoiding any change to theatre practices"]'::jsonb, 0, 'Innovation improves quality and efficiency.', 'Entrepreneurship');
